window.STORYSPROUT_BOOKS[5]={"number":5,"title":"Super Minds 5","edition":"Cambridge University Press · 用户提供的学生用书","teacherAvailable":false,"pageMin":2,"pageMax":127,"pageBase":"books/5/pages","grammarAppendix":true,"sourceNote":"依据本次上传的 Super Minds 5 学生用书编写。书面页码与 PDF 页码一致。故事与阅读均为标明来源的教学改写；新增练习不是原书听力答案。未提供第五册教师用书。","bookSummary":"和 Alex、Phoebe、Patrick 穿越时空，从庞贝、雨林和摇滚舞台走到未来与神秘海上。读懂事件的原因和结果，再用连词讲清完整故事。","storyGuide":"The Time Travellers：一次科学课事故打开黄色时空之门。每次冒险都寻找下一道门；结尾回到学校，却留下时间上的疑问。历史人物与地点被放进虚构故事，不能把情节当作历史事实。","units":[{"id":0,"title":"The Science lesson","zh":"科学课上的时空之门","start":4,"end":9,"icon":"🧪","goal":"读懂实验事故的经过；用过去时讲昨天发生的事。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":118,"vocab":[{"word":"shelf","zh":"架子","example":"The books are on the shelf."},{"word":"goggles","zh":"护目镜","example":"The pupils wear goggles in the lab."},{"word":"instructions","zh":"说明；指令","example":"Read the instructions before you start."},{"word":"apron","zh":"围裙","example":"The teacher is wearing an apron."},{"word":"explosion","zh":"爆炸","example":"There is an explosion in the story."},{"word":"bubbles","zh":"气泡","example":"We can see bubbles in the water."},{"word":"test tube","zh":"试管","example":"The test tube is on the table."},{"word":"liquid","zh":"液体","example":"Water is a liquid."},{"word":"gloves","zh":"手套","example":"The scientist puts on her gloves."},{"word":"powder","zh":"粉末","example":"The powder in the picture is blue."}],"grammar":[{"title":"一般过去时：肯定与否定","rule":"过去发生的动作使用过去式；否定用 did not / didn’t + 动词原形。","examples":[{"en":"I watched a film yesterday.","zh":"昨天我看了一部电影。"},{"en":"She didn’t sing a song.","zh":"她没有唱歌。"}],"questions":[{"prompt":"Yesterday, Alex ___ a film.","options":["watch","watched","watching"],"answer":1,"why":"Yesterday 表示过去，watch 的过去式是 watched。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"Phoebe didn’t ___ Music yesterday.","options":["have","had","having"],"answer":0,"why":"didn’t 后面接动词原形 have。","kind":"grammar","id":"u0-g0-q1"}]},{"title":"过去时提问","rule":"询问过去发生的事用 What did + 主语 + 动词原形；Did 引导的问题可用 Yes/No 回答。","examples":[{"en":"What did you do at school?","zh":"你在学校做了什么？"},{"en":"Did you have a good day?","zh":"你这一天过得好吗？"}],"questions":[{"prompt":"___ did you do yesterday?","options":["Who","What","Where"],"answer":1,"why":"这里询问做了什么事情，用 What。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"Did you ___ a good day?","options":["had","having","have"],"answer":2,"why":"Did 已表示过去，后面的 have 用原形。","kind":"grammar","id":"u0-g1-q1"}]}],"song":{"title":"歌曲：The Time Travellers","page":6,"task":["看 p6，找出三个主角的名字。","用电脑语音读本课故事句；歌曲旋律需另配原书音频。","说一说：过去和未来用英语怎么说？"]},"phonics":{"title":"押韵：听词尾","note":"对应 p6 Rhyming words；以下词对为新编辨音，不是原书音轨。","pairs":[{"a":"day","b":"say"},{"a":"light","b":"night"},{"a":"friend","b":"end"}],"page":6,"questions":[{"prompt":"哪个词和 light 押韵？","options":["late","night","little"],"answer":1,"why":"light /laɪt/ 与 night /naɪt/ 的结尾声音相同。","kind":"phonics","id":"u0-ph-q0"}]},"story":{"title":"The explosion","pages":[8,9],"kind":"依据课文的教学改写","summary":"三个孩子轮流做实验。Patrick 无法读清说明，却继续操作；事故后出现了黄色时空门。这是虚构情节，重点是理解原因并遵守说明。","sentences":[{"en":"Alex, Phoebe and Patrick were in their Science lesson.","zh":"Alex、Phoebe 和 Patrick 正在上科学课。","note":"先交代人物和地点。","id":"u0-story-s0"},{"en":"Alex read the instructions, and Phoebe followed them.","zh":"Alex 读说明，Phoebe 按说明操作。","note":"follow instructions：遵守说明。","id":"u0-story-s1"},{"en":"Their first experiment changed the colour of a brick.","zh":"他们的第一个实验改变了一块砖的颜色。","note":"first 说明事件顺序。","id":"u0-story-s2"},{"en":"In the next experiment, Alex made the brick bigger.","zh":"在下一个实验中，Alex 让砖变大了。","note":"made ... bigger：使……更大。","id":"u0-story-s3"},{"en":"Mr Davis reminded them to read the instructions carefully.","zh":"Davis 老师提醒他们仔细阅读说明。","note":"reminded：提醒。","id":"u0-story-s4"},{"en":"Then Patrick knocked water over the instructions.","zh":"接着 Patrick 打翻了水，水洒在说明上。","note":"knocked ... over：碰翻。","id":"u0-story-s5"},{"en":"The words became impossible to read.","zh":"字变得看不清了。","note":"说明为什么接下来应该停下来求助。","id":"u0-story-s6"},{"en":"Alex wanted to ask the teacher, but Patrick continued without clear instructions.","zh":"Alex 想问老师，但 Patrick 在没有清楚说明的情况下继续操作。","note":"but 表示两人的做法不同。","id":"u0-story-s7"},{"en":"An explosion happened, and a strange yellow gate appeared.","zh":"一场爆炸发生了，一道奇怪的黄色门出现了。","note":"故事把事故与时空之门连接起来；这不是实际实验步骤。","id":"u0-story-s8"},{"en":"The children stepped into the light and disappeared.","zh":"孩子们走进光里，消失了。","note":"故事的悬念：他们去了哪里？","id":"u0-story-s9"}],"questions":[{"prompt":"为什么后来无法读清说明？","options":["说明被水弄湿了。","老师把说明带走了。","说明用另一种语言写成。"],"answer":0,"why":"Patrick 打翻了水，水洒在说明上。","kind":"meaning","id":"u0-story-q0"},{"prompt":"这段故事中，哪一步让风险变大？","options":["仔细阅读说明。","看不清说明仍继续实验。","向老师求助。"],"answer":1,"why":"Patrick 没有按 Alex 的建议求助，而是继续。","kind":"meaning","id":"u0-story-q1"}]},"reading":{"title":"Three different school days","pages":[7],"kind":"依据课文的教学改写","summary":"同样是回答“今天学校怎么样”，三个孩子的感受不同：Alex 普普通通，Patrick 失望，Phoebe 兴奋。","sentences":[{"en":"At home, the children talked about their day at school.","zh":"回家后，孩子们谈起了学校的一天。","note":"talked about：谈论。","id":"u0-reading-s0"},{"en":"Alex said that his day was just OK.","zh":"Alex 说他这一天还可以。","note":"just OK：只是还行。","id":"u0-reading-s1"},{"en":"There was nothing special about his day.","zh":"他没有遇到什么特别的事。","note":"nothing special：没什么特别的。","id":"u0-reading-s2"},{"en":"Patrick thought it was the worst day ever.","zh":"Patrick 认为那是最糟糕的一天。","note":"worst 是 bad 的最高级。","id":"u0-reading-s3"},{"en":"His football team lost six to nil.","zh":"他的足球队以零比六输了。","note":"six to nil：六比零；这里对方得六分。","id":"u0-reading-s4"},{"en":"He was the goalkeeper, so he felt disappointed.","zh":"他是守门员，所以很失望。","note":"so 连接原因和感受；感受是依据语境的解释。","id":"u0-reading-s5"},{"en":"Phoebe was excited about a Geography project.","zh":"Phoebe 对一个地理项目很兴奋。","note":"excited about：对……兴奋。","id":"u0-reading-s6"},{"en":"She was going to do her project on Mexico.","zh":"她要做关于墨西哥的项目。","note":"on 在这里是“关于”。","id":"u0-reading-s7"}],"questions":[{"prompt":"谁因为足球比赛而不开心？","options":["Alex","Phoebe","Patrick"],"answer":2,"why":"Patrick 的球队输了，他是守门员。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"Phoebe 为什么兴奋？","options":["她要做关于墨西哥的地理项目。","她赢了足球赛。","她不用上学了。"],"answer":0,"why":"她谈到了 Geography project on Mexico。","kind":"meaning","id":"u0-reading-q1"}]},"world":{"title":"Read, check, then act","pages":[4,8,9],"kind":"依据单元目标新编","summary":"从科学课故事练习“先读、核对、不会就问”的学习流程。以下为依据单元目标新编，不提供真实化学实验配方。","sentences":[{"en":"Instructions tell us what to do and in what order.","zh":"说明告诉我们做什么，以及按什么顺序做。","note":"order：顺序。","id":"u0-world-s0"},{"en":"In the story, the children need clear instructions.","zh":"故事里，孩子们需要清楚的说明。","note":"clear：清楚的。","id":"u0-world-s1"},{"en":"If the words are wet or unclear, they should stop.","zh":"如果文字湿了或不清楚，他们就应该停下来。","note":"unclear：不清楚的。","id":"u0-world-s2"},{"en":"A teacher can explain the next step.","zh":"老师可以解释下一步。","note":"explain：解释。","id":"u0-world-s3"},{"en":"Goggles and gloves are useful, but they do not replace instructions.","zh":"护目镜和手套有用，但不能代替说明。","note":"replace：代替。","id":"u0-world-s4"},{"en":"Careful questions are part of good learning.","zh":"认真提问是良好学习的一部分。","note":"part of：……的一部分。","id":"u0-world-s5"}],"questions":[{"prompt":"读不清下一步时，文中建议做什么？","options":["随意猜一猜。","停下来问老师。","加快速度。"],"answer":1,"why":"第四句说老师可以解释下一步。","kind":"meaning","id":"u0-world-q0"},{"prompt":"哪句话最符合这段短文？","options":["认真提问能帮助学习。","穿了手套就不用看说明。","不清楚也应该继续。"],"answer":0,"why":"最后一句点明：提问是良好学习的一部分。","kind":"meaning","id":"u0-world-q1"}]},"create":{"title":"用四步讲清科学课事故","pages":[7,8,9],"tasks":["按“人物—正常操作—出错原因—结果”写四条笔记。","用过去时写 5–7 句；至少包含一个 but 或 so。","口头讲给家长听，再用中文解释 Patrick 应在哪里停下来。"],"frame":"The children were in ...\nFirst, ...\nThen, ...\nPatrick ... but ...\nAn explosion ...\nFinally, ...","model":"The children were in the Science lab. At first, they followed the instructions. Then water fell onto the instructions. Alex wanted to ask the teacher, but Patrick continued. An explosion happened and a yellow gate appeared. The children walked into the light.","success":"能说清说明被弄湿这一原因、继续操作与事故的关系，并按顺序讲述。","teacher":"依据 p7 过去经历问答和 p8–9 故事新编复述任务；不是实验活动。"},"extra":[],"questions":[{"prompt":"Yesterday, Alex ___ a film.","options":["watch","watched","watching"],"answer":1,"why":"Yesterday 表示过去，watch 的过去式是 watched。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"Phoebe didn’t ___ Music yesterday.","options":["have","had","having"],"answer":0,"why":"didn’t 后面接动词原形 have。","kind":"grammar","id":"u0-g0-q1"},{"prompt":"___ did you do yesterday?","options":["Who","What","Where"],"answer":1,"why":"这里询问做了什么事情，用 What。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"Did you ___ a good day?","options":["had","having","have"],"answer":2,"why":"Did 已表示过去，后面的 have 用原形。","kind":"grammar","id":"u0-g1-q1"},{"prompt":"为什么后来无法读清说明？","options":["说明被水弄湿了。","老师把说明带走了。","说明用另一种语言写成。"],"answer":0,"why":"Patrick 打翻了水，水洒在说明上。","kind":"meaning","id":"u0-story-q0"},{"prompt":"这段故事中，哪一步让风险变大？","options":["仔细阅读说明。","看不清说明仍继续实验。","向老师求助。"],"answer":1,"why":"Patrick 没有按 Alex 的建议求助，而是继续。","kind":"meaning","id":"u0-story-q1"},{"prompt":"谁因为足球比赛而不开心？","options":["Alex","Phoebe","Patrick"],"answer":2,"why":"Patrick 的球队输了，他是守门员。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"Phoebe 为什么兴奋？","options":["她要做关于墨西哥的地理项目。","她赢了足球赛。","她不用上学了。"],"answer":0,"why":"她谈到了 Geography project on Mexico。","kind":"meaning","id":"u0-reading-q1"},{"prompt":"读不清下一步时，文中建议做什么？","options":["随意猜一猜。","停下来问老师。","加快速度。"],"answer":1,"why":"第四句说老师可以解释下一步。","kind":"meaning","id":"u0-world-q0"},{"prompt":"哪句话最符合这段短文？","options":["认真提问能帮助学习。","穿了手套就不用看说明。","不清楚也应该继续。"],"answer":0,"why":"最后一句点明：提问是良好学习的一部分。","kind":"meaning","id":"u0-world-q1"},{"prompt":"哪个词和 light 押韵？","options":["late","night","little"],"answer":1,"why":"light /laɪt/ 与 night /naɪt/ 的结尾声音相同。","kind":"phonics","id":"u0-ph-q0"}]},{"id":1,"title":"Disaster!","zh":"灾难来临","start":10,"end":21,"icon":"🌋","goal":"识别过去进行时；说清庞贝故事中的危险、提醒与逃离。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":119,"vocab":[{"word":"smoke","zh":"烟","example":"Dark smoke rises into the sky."},{"word":"volcano","zh":"火山","example":"The volcano is far from the town."},{"word":"temple","zh":"神庙","example":"There is an old temple in the city."},{"word":"columns","zh":"柱子","example":"The building has tall columns."},{"word":"fountain","zh":"喷泉","example":"Water falls into the fountain."},{"word":"theatre","zh":"剧院","example":"The theatre is next to the square."},{"word":"horse and cart","zh":"马车","example":"A horse and cart moves down the road."},{"word":"servant","zh":"仆人","example":"A servant carries food in the story."},{"word":"statue","zh":"雕像","example":"We saw a stone statue."}],"grammar":[{"title":"过去进行时与 when","rule":"was/were + 动词-ing 表示过去某时正在做；when 可引出突然发生的事情。","examples":[{"en":"I was reading when the phone rang.","zh":"电话响时我正在读书。"},{"en":"They were playing when it started to rain.","zh":"开始下雨时他们正在玩。"}],"questions":[{"prompt":"When the ground shook, I ___ a book.","options":["was reading","readed","am reading"],"answer":0,"why":"过去某时正在读书，用 was reading。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"The boys ___ football when it happened.","options":["was playing","were playing","plays"],"answer":1,"why":"复数主语 boys 配 were playing。","kind":"grammar","id":"u1-g0-q1"}]},{"title":"while：两个同时进行的动作","rule":"while 引导过去正在发生的背景动作；两个动作都在进行时可各用过去进行时。","examples":[{"en":"While Mum was reading, I was drawing.","zh":"妈妈在读书时，我在画画。"},{"en":"The dog was sleeping while we were talking.","zh":"我们在说话时狗在睡觉。"}],"questions":[{"prompt":"While Dad was cooking, we ___ the table.","options":["are setting","were setting","sets"],"answer":1,"why":"两个动作发生在过去并且同时进行，用 were setting。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"Which word means “当……的时候” here?","options":["because","tomorrow","while"],"answer":2,"why":"while 可连接同时发生的动作。","kind":"grammar","id":"u1-g1-q1"}]}],"song":{"title":"歌曲：Danger!","page":12,"task":["在 p12 找出表示危险的词。","用 was/were + -ing 说一个故事背景。","读懂意思后再配合原书音频唱；电脑语音只负责读句子。"]},"phonics":{"title":"词尾不发音的 e","note":"对应 p12 final e。以下是同规律的新编词对，比较加 e 前后元音。","pairs":[{"a":"cap","b":"cape"},{"a":"cut","b":"cute"},{"a":"hop","b":"hope"}],"page":12,"questions":[{"prompt":"哪个词通常有不发音的词尾 e，并把 a 读成长音？","options":["cap","cat","cape"],"answer":2,"why":"cape 中结尾 e 不单独发音，a 读 /eɪ/。","kind":"phonics","id":"u1-ph-q0"}]},"story":{"title":"A narrow escape","pages":[14,15],"kind":"依据课文的教学改写","summary":"Phoebe 认出庞贝和火山危险，想提醒城里的人。爆发时，三个孩子发现黄色门并逃离。重点是原因、行动和结果。","sentences":[{"en":"Phoebe ran out of the city, and the boys followed her up a hill.","zh":"Phoebe 跑出城，两个男孩跟着她跑上小山。","note":"followed：跟随。","id":"u1-story-s0"},{"en":"She recognised Pompeii from her History lessons.","zh":"她从历史课所学认出了庞贝。","note":"recognised：认出。","id":"u1-story-s1"},{"en":"She was afraid that the volcano was going to erupt.","zh":"她担心火山将要喷发。","note":"was going to：当时预计将要。","id":"u1-story-s2"},{"en":"A loud noise came from the volcano, and dark smoke rose into the sky.","zh":"火山发出巨响，黑烟升上天空。","note":"故事用声音和画面表现危险。","id":"u1-story-s3"},{"en":"Phoebe wanted to warn the people in the city.","zh":"Phoebe 想提醒城里的人。","note":"warn：警告、提醒危险。","id":"u1-story-s4"},{"en":"The children returned, but the people did not understand their words.","zh":"孩子们返回城里，但人们不理解他们的话。","note":"but 引出沟通困难。","id":"u1-story-s5"},{"en":"Then the volcano erupted, and everyone became frightened.","zh":"随后火山喷发了，大家都害怕起来。","note":"then 推动事件发展。","id":"u1-story-s6"},{"en":"Through the smoke, Alex saw a yellow light.","zh":"透过烟雾，Alex 看见一道黄色的光。","note":"through：穿过。","id":"u1-story-s7"},{"en":"Phoebe recognised the gate from the Science lab.","zh":"Phoebe 认出了科学实验室里出现过的那道门。","note":"前后两章的联系。","id":"u1-story-s8"},{"en":"The three friends ran to the gate and disappeared through it.","zh":"三个朋友跑向门，从门里消失了。","note":"narrow escape：险些出事但逃脱。","id":"u1-story-s9"}],"questions":[{"prompt":"Phoebe 为什么认出这个城市很危险？","options":["她以前在这座城市住过。","历史课帮助她认出了庞贝和火山。","当地居民刚向她解释过火山历史。"],"answer":1,"why":"文中提到 she recognised Pompeii from her History lessons。","kind":"meaning","id":"u1-story-q0"},{"prompt":"故事结尾，孩子们如何离开？","options":["乘马车回学校。","躲进神庙睡觉。","穿过黄色时空门。"],"answer":2,"why":"Alex 发现黄色光，孩子们跑向门并消失。","kind":"meaning","id":"u1-story-q1"}]},"reading":{"title":"Understanding natural disasters","pages":[16],"kind":"依据课文的教学改写","summary":"本页介绍不同自然灾害及其影响。改写保留分类、观察和了解风险的核心，不把旧教材中的年度统计当作现在的排名。","sentences":[{"en":"Natural disasters can happen in different parts of the world.","zh":"自然灾害可能发生在世界不同地方。","note":"different parts：不同地区。","id":"u1-reading-s0"},{"en":"Some disasters are connected with the weather.","zh":"有些灾害与天气有关。","note":"connected with：与……有关。","id":"u1-reading-s1"},{"en":"Storms, floods and hurricanes are examples.","zh":"暴风雨、洪水和飓风就是例子。","note":"examples：例子。","id":"u1-reading-s2"},{"en":"Scientists use equipment to study earthquakes and volcanoes.","zh":"科学家利用设备研究地震和火山。","note":"equipment 是不可数名词。","id":"u1-reading-s3"},{"en":"It can be difficult to know exactly when a disaster will happen.","zh":"准确知道灾害何时发生可能很困难。","note":"exactly：准确地。","id":"u1-reading-s4"},{"en":"Floods can damage homes, roads and fields.","zh":"洪水会损坏住宅、道路和农田。","note":"damage：损害。","id":"u1-reading-s5"},{"en":"Forest fires may begin after lightning or because people are careless.","zh":"森林火灾可能由闪电或人们的疏忽引起。","note":"because 表示原因。","id":"u1-reading-s6"},{"en":"Learning about local risks helps people prepare and listen to warnings.","zh":"了解当地风险有助于人们做准备并留意预警。","note":"local：当地的；warnings：预警。","id":"u1-reading-s7"}],"questions":[{"prompt":"哪项属于文中与天气有关的灾害？","options":["洪水。","地震。","火山喷发。"],"answer":0,"why":"第三句把 floods 列为例子。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"文章对“准确知道灾害何时发生”怎么说？","options":["总能精确预测时间。","可能很困难。","只观察一次就能确定时间。"],"answer":1,"why":"第五句说 It can be difficult to know exactly when。","kind":"meaning","id":"u1-reading-q1"}]},"world":{"title":"Inside a volcano","pages":[18,19],"kind":"依据课文的教学改写","summary":"用七句认识 magma、lava、crater、ash。教材的模型活动可在原书查看；这里用画图代替实际操作。","sentences":[{"en":"Deep inside Earth, some rock is so hot that it is melted.","zh":"地球深处有些岩石非常热，处于熔融状态。","note":"melted rock：熔融岩石。","id":"u1-world-s0"},{"en":"Melted rock below the surface is called magma.","zh":"地表下面的熔融岩石叫 magma（岩浆）。","note":"below the surface：在地表下面。","id":"u1-world-s1"},{"en":"Magma can collect in a chamber underground.","zh":"岩浆可以聚集在地下的岩浆房中。","note":"chamber：腔室；这里指岩浆房。","id":"u1-world-s2"},{"en":"Pressure can help push magma upwards.","zh":"压力能促使岩浆向上移动。","note":"upwards：向上。","id":"u1-world-s3"},{"en":"A crater is an opening at the top of a volcano.","zh":"crater 是火山顶部的一个开口。","note":"用图像把单词和位置联系起来。","id":"u1-world-s4"},{"en":"When magma reaches the surface, we call it lava.","zh":"岩浆到达地表后，我们称它为 lava（熔岩）。","note":"区分 magma 和 lava 所在的位置。","id":"u1-world-s5"},{"en":"An eruption can send ash and gases into the air.","zh":"一次喷发可能把火山灰和气体送进空中。","note":"ash：火山灰；eruption：喷发。","id":"u1-world-s6"}],"questions":[{"prompt":"地表下面的熔融岩石叫作什么？","options":["lava","magma","ash"],"answer":1,"why":"第二句直接给出了 magma 的定义。","kind":"meaning","id":"u1-world-q0"},{"prompt":"岩浆到达地表后通常称为什么？","options":["lava","crater","magma"],"answer":0,"why":"第六句区分了地下的 magma 和地表的 lava。","kind":"meaning","id":"u1-world-q1"}]},"create":{"title":"小小灾害解说员","pages":[17,18,20],"tasks":["画一座火山并标出 magma、crater、lava。","用 5–7 句解释一种灾害；至少一句包含 was/were + -ing。","先看关键词讲 45 秒，再回答“发生了什么？人们当时在做什么？”"],"frame":"This talk is about ...\nIt can ...\nIn my imaginary report, people were ... when ...\nThe important words are ...\nWe can learn ...","model":"This talk is about volcanoes. Magma is melted rock below the ground. When it reaches the surface, we call it lava. In my imaginary report, people were walking when they saw smoke. They listened to the adults and the official warnings. Learning the words helps us understand the report.","success":"能区分词语、交代过去背景和发生的事；想象报道要明确说 imaginary，不编造真实灾害数字。","teacher":"依据 p17 灾害短文写作、p18 火山知识与 p20 展示目标新编。"},"extra":[],"questions":[{"prompt":"When the ground shook, I ___ a book.","options":["was reading","readed","am reading"],"answer":0,"why":"过去某时正在读书，用 was reading。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"The boys ___ football when it happened.","options":["was playing","were playing","plays"],"answer":1,"why":"复数主语 boys 配 were playing。","kind":"grammar","id":"u1-g0-q1"},{"prompt":"While Dad was cooking, we ___ the table.","options":["are setting","were setting","sets"],"answer":1,"why":"两个动作发生在过去并且同时进行，用 were setting。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"Which word means “当……的时候” here?","options":["because","tomorrow","while"],"answer":2,"why":"while 可连接同时发生的动作。","kind":"grammar","id":"u1-g1-q1"},{"prompt":"Phoebe 为什么认出这个城市很危险？","options":["她以前在这座城市住过。","历史课帮助她认出了庞贝和火山。","当地居民刚向她解释过火山历史。"],"answer":1,"why":"文中提到 she recognised Pompeii from her History lessons。","kind":"meaning","id":"u1-story-q0"},{"prompt":"故事结尾，孩子们如何离开？","options":["乘马车回学校。","躲进神庙睡觉。","穿过黄色时空门。"],"answer":2,"why":"Alex 发现黄色光，孩子们跑向门并消失。","kind":"meaning","id":"u1-story-q1"},{"prompt":"哪项属于文中与天气有关的灾害？","options":["洪水。","地震。","火山喷发。"],"answer":0,"why":"第三句把 floods 列为例子。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"文章对“准确知道灾害何时发生”怎么说？","options":["总能精确预测时间。","可能很困难。","只观察一次就能确定时间。"],"answer":1,"why":"第五句说 It can be difficult to know exactly when。","kind":"meaning","id":"u1-reading-q1"},{"prompt":"地表下面的熔融岩石叫作什么？","options":["lava","magma","ash"],"answer":1,"why":"第二句直接给出了 magma 的定义。","kind":"meaning","id":"u1-world-q0"},{"prompt":"岩浆到达地表后通常称为什么？","options":["lava","crater","magma"],"answer":0,"why":"第六句区分了地下的 magma 和地表的 lava。","kind":"meaning","id":"u1-world-q1"},{"prompt":"哪个词通常有不发音的词尾 e，并把 a 读成长音？","options":["cap","cat","cape"],"answer":2,"why":"cape 中结尾 e 不单独发音，a 读 /eɪ/。","kind":"phonics","id":"u1-ph-q0"}]},{"id":2,"title":"In the rainforest","zh":"走进雨林","start":22,"end":33,"icon":"🌿","goal":"理解 have to 的规则；沿时间线复述雨林冒险，并解释为什么要保护雨林。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":120,"vocab":[{"word":"creeper","zh":"攀缘植物；藤蔓","example":"The creeper grows up a tree."},{"word":"beak","zh":"鸟喙","example":"The bird has a long beak."},{"word":"toucan","zh":"巨嘴鸟","example":"A toucan sits on the branch."},{"word":"sloth","zh":"树懒","example":"The sloth moves slowly."},{"word":"branch","zh":"树枝","example":"The branch is high above us."},{"word":"anaconda","zh":"水蚺","example":"The anaconda is a large snake."},{"word":"pool","zh":"水潭","example":"There is a small pool by the trees."},{"word":"jaguar","zh":"美洲豹","example":"A jaguar has a spotted coat."},{"word":"anteater","zh":"食蚁兽","example":"The anteater has a long nose."}],"grammar":[{"title":"较大的数字","rule":"hundred 是百，thousand 是千，million 是百万；具体数字后 hundred/thousand/million 不加 s。","examples":[{"en":"Two hundred birds live here.","zh":"这里生活着两百只鸟。"},{"en":"The number is one million.","zh":"这个数字是一百万。"}],"questions":[{"prompt":"200,000 读作什么？","options":["two hundred","two thousand","two hundred thousand"],"answer":2,"why":"200,000 是二十万，即 two hundred thousand。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"5,000,000 读作什么？","options":["five million","five millions","five thousand"],"answer":0,"why":"具体数字后用单数 million。","kind":"grammar","id":"u2-g0-q1"}]},{"title":"have to / don’t have to","rule":"have to 表示必须；don’t have to 表示不必，不是禁止。过去必须做可用 had to。","examples":[{"en":"You have to follow the guide.","zh":"你必须跟着向导。"},{"en":"You don’t have to bring food.","zh":"你不必带食物。"}],"questions":[{"prompt":"You don’t have to bring food. 这句话是什么意思？","options":["禁止带食物。","不必带食物。","必须带食物。"],"answer":1,"why":"don’t have to 表示没有这个必要。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"___ I have to wear boots?","options":["Am","Did","Do"],"answer":2,"why":"询问现在是否有义务，用 Do I have to ...?","kind":"grammar","id":"u2-g1-q1"}]}],"song":{"title":"功能对话：Asking for instructions","page":24,"task":["扮演游戏玩家，问 What do you have to do?","为一个纸上寻宝游戏说两条规则。","追问 Is there anything else?，让搭档补充一条。"]},"phonics":{"title":"读清数字词尾","note":"本单元 p24 是功能对话，没有独立歌曲拼读栏。这里结合 p23 数字，提供新编口语辨音。","pairs":[{"a":"fourteen","b":"forty"},{"a":"sixteen","b":"sixty"},{"a":"nineteen","b":"ninety"}],"page":23,"questions":[{"prompt":"sixteen 表示哪个数字？","options":["60","6","16"],"answer":2,"why":"sixteen 是 16；sixty 是 60，读音和词尾都不同。","kind":"phonics","id":"u2-ph-q0"}]},"story":{"title":"The present","pages":[26,27],"kind":"依据课文的教学改写","summary":"饥饿的孩子们在雨林中寻找帮助。他们误把吼猴的声音当成美洲豹，随后遇见村民、分享食物，再找到时空门。","sentences":[{"en":"The children walked through the rainforest, looking for a way out.","zh":"孩子们穿过雨林，寻找出路。","note":"looking for：寻找。","id":"u2-story-s0"},{"en":"They followed a river because they hoped to find a village.","zh":"他们沿着河走，希望找到村庄。","note":"because 解释选择路线的原因。","id":"u2-story-s1"},{"en":"A loud animal noise frightened them.","zh":"一阵很大的动物叫声吓到了他们。","note":"frightened：使害怕。","id":"u2-story-s2"},{"en":"Patrick thought it was a jaguar, but it was a howler monkey.","zh":"Patrick 以为那是美洲豹，但其实是一只吼猴。","note":"thought 与 was 对比“猜想”和“事实”。","id":"u2-story-s3"},{"en":"Later, they met a man who led them to a village.","zh":"后来，他们遇到一个人，他带他们来到村庄。","note":"led 是 lead 的过去式。","id":"u2-story-s4"},{"en":"Alex gave his penknife to an older man as a present.","zh":"Alex 把自己的小折刀作为礼物送给一位老人。","note":"这是原故事情节，不是让孩子携带刀具的任务。","id":"u2-story-s5"},{"en":"The villagers shared food with the three hungry visitors.","zh":"村民和三个饥饿的来客分享了食物。","note":"shared：分享。","id":"u2-story-s6"},{"en":"After dinner, a man showed them a waterfall and a yellow glow.","zh":"饭后，一个人带他们看瀑布和那里的黄色光芒。","note":"after dinner：晚饭后。","id":"u2-story-s7"},{"en":"In the adventure, Patrick swung through the gate on a creeper.","zh":"在这个冒险故事中，Patrick 抓住藤蔓荡过了时空门。","note":"故事中的危险动作，不要模仿。","id":"u2-story-s8"},{"en":"Alex was afraid, so Phoebe went with him through the light.","zh":"Alex 害怕，所以 Phoebe 陪他一起穿过光。","note":"so 连接害怕与同伴支持。","id":"u2-story-s9"}],"questions":[{"prompt":"最初让孩子们害怕的声音其实来自谁？","options":["美洲豹。","吼猴。","巨嘴鸟。"],"answer":1,"why":"他们后来发现树上的动物是 howler monkey。","kind":"meaning","id":"u2-story-q0"},{"prompt":"Alex 害怕时，Phoebe 做了什么？","options":["陪他一起穿过门。","让他独自留在瀑布边。","和他一起返回村庄。"],"answer":0,"why":"最后一句交代同伴的支持。","kind":"meaning","id":"u2-story-q1"}]},"reading":{"title":"A meeting from the air","pages":[29],"kind":"依据课文的教学改写","summary":"教材用 2008 年亚马孙上空的一次观察，引出保护森林和尊重不同生活方式。注意：这是对书中报道的改写，不是对当地社群现状的更新。","sentences":[{"en":"The article describes a flight over the Amazon rainforest in May 2008.","zh":"文章描述了 2008 年五月一次飞越亚马孙雨林的经历。","note":"把时间说清楚，避免当成今日新闻。","id":"u2-reading-s0"},{"en":"The pilot saw huts below the small plane.","zh":"飞行员看见小飞机下面有一些小屋。","note":"below：在……下面。","id":"u2-reading-s1"},{"en":"People on the ground pointed bows and arrows towards the plane.","zh":"地面上的人把弓箭指向飞机。","note":"towards：朝向。","id":"u2-reading-s2"},{"en":"The people in the plane took photographs and flew away.","zh":"飞机上的人拍了照片后飞走了。","note":"按时间顺序读动作。","id":"u2-reading-s3"},{"en":"The article suggests that the people on the ground felt frightened.","zh":"文章认为地面上的人感到了害怕。","note":"suggests：提出一种解释，而不是读心。","id":"u2-reading-s4"},{"en":"It explains that cutting down forests threatens people's homes.","zh":"文章解释说，砍伐森林威胁着人们的家园。","note":"threatens：威胁。","id":"u2-reading-s5"},{"en":"It also describes risks when people with little outside contact meet outsiders.","zh":"它也描述了很少与外界接触的人群遇到外来者时的风险。","note":"不把一种生活方式当成所有群体的共同情况。","id":"u2-reading-s6"},{"en":"The main message is to protect their land and respect their choices.","zh":"主要意思是保护他们的土地，并尊重他们的选择。","note":"respect：尊重。","id":"u2-reading-s7"}],"questions":[{"prompt":"这篇教材报道描述的飞行发生在什么时候？","options":["2008 年八月。","2008 年五月。","2018 年五月。"],"answer":1,"why":"第一句明确标出报道的时间。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"哪一项最接近文章的核心意思？","options":["每个地方的人生活都完全相同。","为了拍照应该闯入别人家园。","保护土地，尊重不同社群的生活。"],"answer":2,"why":"结尾总结了保护与尊重的主题。","kind":"meaning","id":"u2-reading-q1"}]},"world":{"title":"Why rainforests matter","pages":[30,31],"kind":"依据课文的教学改写","summary":"雨林给许多生物和人提供家园，也参与水循环。砍伐与清地会破坏这些家园。","sentences":[{"en":"Rainforests are places where a great deal of rain falls.","zh":"雨林是降雨很多的地方。","note":"a great deal of：大量的。","id":"u2-world-s0"},{"en":"Many kinds of plants and animals live there.","zh":"许多种类的植物和动物生活在那里。","note":"many kinds of：许多种类的。","id":"u2-world-s1"},{"en":"Rainforest plants take in water from the ground.","zh":"雨林植物从地面吸收水分。","note":"take in：吸收。","id":"u2-world-s2"},{"en":"They release water vapour into the air as part of the water cycle.","zh":"它们把水蒸气释放到空气中，参与水循环。","note":"water vapour：水蒸气。","id":"u2-world-s3"},{"en":"Forests are also homes for people with their own languages and traditions.","zh":"森林也是有各自语言和传统的人们的家园。","note":"traditions：传统。","id":"u2-world-s4"},{"en":"Logging removes trees, and land may also be cleared for farms.","zh":"伐木会移走树木，土地也可能被清理出来建设农场。","note":"logging：伐木；cleared：清理。","id":"u2-world-s5"},{"en":"Protecting a forest means protecting many connected living things.","zh":"保护森林，就是保护许多彼此联系的生命。","note":"connected：相互联系的。","id":"u2-world-s6"}],"questions":[{"prompt":"植物释放到空气中的水是什么形式？","options":["冰块。","液体水滴。","水蒸气。"],"answer":2,"why":"第四句说明 water vapour。","kind":"meaning","id":"u2-world-q0"},{"prompt":"为什么砍伐森林不只影响树木？","options":["森林也是动物和人们的家园。","所有雨林动物都能马上搬到城市。","没有树木就会有更多同样的栖息地。"],"answer":0,"why":"第二、第五句说明多种动物、植物和人住在森林。","kind":"meaning","id":"u2-world-q1"}]},"create":{"title":"设计一张雨林说明卡","pages":[28,30,31,33],"tasks":["从本课选一种动物，写出外形、栖息地和一个教材中可核对的特点。","写两句 have to / don’t have to 的纸上探险游戏规则。","用 5–7 句介绍雨林为什么重要，并说明你的动物卡信息来自哪一页。"],"frame":"My animal is ...\nIt has ...\nIt lives ...\nIn our paper game, you have to ...\nYou don’t have to ...\nRainforests are important because ...","model":"My animal is a toucan. It has a large beak. It lives in the rainforest. In our paper game, you have to find the bird card. You don’t have to climb a real tree. Rainforests are important because many living things depend on them.","success":"能说清一个动物特点、两条游戏规则和保护雨林的一条原因；不猜测原书听力空缺数字。","teacher":"依据 p28 动物卡、p30–31 雨林主题和 p33 描写目标新编；提供的规则仅用于纸上游戏。"},"extra":[],"questions":[{"prompt":"200,000 读作什么？","options":["two hundred","two thousand","two hundred thousand"],"answer":2,"why":"200,000 是二十万，即 two hundred thousand。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"5,000,000 读作什么？","options":["five million","five millions","five thousand"],"answer":0,"why":"具体数字后用单数 million。","kind":"grammar","id":"u2-g0-q1"},{"prompt":"You don’t have to bring food. 这句话是什么意思？","options":["禁止带食物。","不必带食物。","必须带食物。"],"answer":1,"why":"don’t have to 表示没有这个必要。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"___ I have to wear boots?","options":["Am","Did","Do"],"answer":2,"why":"询问现在是否有义务，用 Do I have to ...?","kind":"grammar","id":"u2-g1-q1"},{"prompt":"最初让孩子们害怕的声音其实来自谁？","options":["美洲豹。","吼猴。","巨嘴鸟。"],"answer":1,"why":"他们后来发现树上的动物是 howler monkey。","kind":"meaning","id":"u2-story-q0"},{"prompt":"Alex 害怕时，Phoebe 做了什么？","options":["陪他一起穿过门。","让他独自留在瀑布边。","和他一起返回村庄。"],"answer":0,"why":"最后一句交代同伴的支持。","kind":"meaning","id":"u2-story-q1"},{"prompt":"这篇教材报道描述的飞行发生在什么时候？","options":["2008 年八月。","2008 年五月。","2018 年五月。"],"answer":1,"why":"第一句明确标出报道的时间。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"哪一项最接近文章的核心意思？","options":["每个地方的人生活都完全相同。","为了拍照应该闯入别人家园。","保护土地，尊重不同社群的生活。"],"answer":2,"why":"结尾总结了保护与尊重的主题。","kind":"meaning","id":"u2-reading-q1"},{"prompt":"植物释放到空气中的水是什么形式？","options":["冰块。","液体水滴。","水蒸气。"],"answer":2,"why":"第四句说明 water vapour。","kind":"meaning","id":"u2-world-q0"},{"prompt":"为什么砍伐森林不只影响树木？","options":["森林也是动物和人们的家园。","所有雨林动物都能马上搬到城市。","没有树木就会有更多同样的栖息地。"],"answer":0,"why":"第二、第五句说明多种动物、植物和人住在森林。","kind":"meaning","id":"u2-world-q1"},{"prompt":"sixteen 表示哪个数字？","options":["60","6","16"],"answer":2,"why":"sixteen 是 16；sixty 是 60，读音和词尾都不同。","kind":"phonics","id":"u2-ph-q0"}]},{"id":3,"title":"The rock 'n' roll show","zh":"摇滚演出","start":34,"end":45,"icon":"🎸","goal":"用 going to 讲计划，读懂钟点；理解坚持练习的故事。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":121,"vocab":[{"word":"spotlight","zh":"聚光灯","example":"The spotlight shines on the singer."},{"word":"bodyguards","zh":"保镖","example":"The bodyguards stand by the door."},{"word":"fans","zh":"歌迷；爱好者","example":"The fans clap after the song."},{"word":"electric guitar","zh":"电吉他","example":"She plays an electric guitar."},{"word":"bass guitar","zh":"低音吉他；贝斯","example":"The bass guitar has a deep sound."},{"word":"backing singers","zh":"伴唱歌手","example":"The backing singers stand behind the star."},{"word":"dancer","zh":"舞者","example":"The dancer moves to the music."},{"word":"drum kit","zh":"架子鼓","example":"The drummer sits at the drum kit."},{"word":"stage","zh":"舞台","example":"The band walks onto the stage."}],"grammar":[{"title":"be going to：计划","rule":"am/is/are going to + 动词原形表示已经打算做的事；提问把 be 放在主语前。","examples":[{"en":"I’m going to practise tonight.","zh":"今晚我打算练习。"},{"en":"Are you going to sing?","zh":"你打算唱歌吗？"}],"questions":[{"prompt":"She ___ going to play the guitar.","options":["am","is","are"],"answer":1,"why":"She 配 is。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"Are you going to ___ a new song?","options":["write","wrote","writing"],"answer":0,"why":"going to 后面接动词原形 write。","kind":"grammar","id":"u3-g0-q1"}]},{"title":"读钟点：past 与 to","rule":"past 表示几点过几分；to 表示离下一个整点还差几分。quarter 是一刻钟，half 是半小时。","examples":[{"en":"It’s twenty past five.","zh":"现在是五点二十分。"},{"en":"It’s a quarter to six.","zh":"现在是差一刻六点，也就是五点四十五分。"}],"questions":[{"prompt":"twenty to six 是几点？","options":["6:20","5:20","5:40"],"answer":2,"why":"距六点还差二十分钟，所以是 5:40。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"5:15 应该怎么说？","options":["a quarter past five","a quarter to five","half past five"],"answer":0,"why":"过五点十五分钟，用 a quarter past five。","kind":"grammar","id":"u3-g1-q1"}]}],"song":{"title":"歌曲：Come rock with me","page":36,"task":["找出歌词里的 going to。","用两句英语介绍自己的练习计划。","跟读新编例句；唱歌请配原书音频。"]},"phonics":{"title":"rock 与 roll 的元音","note":"对应 p36 rock or roll，比较英式常见读音 /ɒ/ 与 /əʊ/。电脑语音口音可能不同。","pairs":[{"a":"rock","b":"roll"},{"a":"Tom","b":"home"},{"a":"sock","b":"go"}],"page":36,"questions":[{"prompt":"哪个词和 roll 的元音相同？","options":["sock","home","rock"],"answer":1,"why":"roll 与 home 通常都有 /əʊ/（美式常为 /oʊ/）。","kind":"phonics","id":"u3-ph-q0"}]},"story":{"title":"Elvis","pages":[38,39],"kind":"依据课文的教学改写","summary":"孩子们遇见 Elvis，了解到明星也需要安静。他们用换装计划帮他离开人群，随后接受款待，再次踏进时空门。与历史人物见面的情节是虚构的。","sentences":[{"en":"After the show, Patrick spoke to Elvis Presley.","zh":"演出后，Patrick 和 Elvis Presley 说话。","note":"after the show：演出之后。","id":"u3-story-s0"},{"en":"Patrick said that his grandmother loved Elvis and owned his CDs.","zh":"Patrick 说奶奶喜欢 Elvis，还拥有他的 CD。","note":"owned：拥有。","id":"u3-story-s1"},{"en":"Elvis was confused because CDs were unfamiliar to him in that time.","zh":"Elvis 很困惑，因为在那个年代，CD 对他很陌生。","note":"时间旅行造成了有趣的误会。","id":"u3-story-s2"},{"en":"In his dressing room, Elvis explained that many fans were waiting outside.","zh":"在化妆间里，Elvis 解释说外面有许多歌迷等候。","note":"dressing room：化妆间。","id":"u3-story-s3"},{"en":"He wanted some peace and quiet, and Alex thought of a plan.","zh":"他想得到一点安静，Alex 想出了一个计划。","note":"peace and quiet：宁静。","id":"u3-story-s4"},{"en":"Alex used a wig, glasses and a long coat to look like Elvis.","zh":"Alex 用假发、眼镜和长外套装扮成 Elvis。","note":"look like：看起来像。","id":"u3-story-s5"},{"en":"In the story, Alex sat on Patrick's shoulders and attracted the fans at the back door.","zh":"故事中，Alex 坐在 Patrick 肩上，在后门吸引歌迷注意。","note":"只复述虚构情节，不模仿危险或欺骗行为。","id":"u3-story-s6"},{"en":"Meanwhile, the real Elvis left by the front door with Phoebe.","zh":"与此同时，真正的 Elvis 和 Phoebe 从前门离开。","note":"meanwhile：与此同时。","id":"u3-story-s7"},{"en":"Elvis thanked the children with a meal at his hotel.","zh":"Elvis 在酒店用一顿饭感谢孩子们。","note":"thank ... with：用……表示感谢。","id":"u3-story-s8"},{"en":"They enjoyed his company, but the yellow gate appeared and they had to leave.","zh":"他们和他相处很开心，但黄色门出现了，他们必须离开。","note":"but 表示“想留”和“必须走”的对比。","id":"u3-story-s9"}],"questions":[{"prompt":"Elvis 为什么不理解 Patrick 提到的 CD？","options":["在这个故事所处的年代，CD 对他很陌生。","他以为 Patrick 在谈自己的新演出。","他正在向 Patrick 解释如何播放 CD。"],"answer":0,"why":"时间旅行让 Patrick 用了 Elvis 所处年代不熟悉的词。","kind":"meaning","id":"u3-story-q0"},{"prompt":"真正的 Elvis 从哪里离开剧院？","options":["后门，独自一人。","前门，和 Phoebe 一起。","后门，和 Alex 一起。"],"answer":1,"why":"第八句明确说明 front door with Phoebe。","kind":"meaning","id":"u3-story-q1"}]},"reading":{"title":"Misha keeps playing","pages":[41],"kind":"依据课文的教学改写","summary":"Misha 两次被乐队拒绝，但她继续享受演奏。制作人听到她的音乐后，看到了她的能力。故事强调坚持，而不是只看外形或音量。","sentences":[{"en":"Misha wanted to join a band and play her guitar.","zh":"Misha 想加入乐队并弹吉他。","note":"wanted to：想要。","id":"u3-reading-s0"},{"en":"She felt nervous when she met Mike and his band.","zh":"遇到 Mike 和他的乐队时，她很紧张。","note":"nervous：紧张的。","id":"u3-reading-s1"},{"en":"Mike said she played well but was not loud enough.","zh":"Mike 说她弹得不错，但声音不够大。","note":"not ... enough：不够……。","id":"u3-reading-s2"},{"en":"Later, another band rejected her because they did not think she looked right.","zh":"后来，另一个乐队拒绝她，因为他们认为她的样子不合适。","note":"rejected：拒绝接受。","id":"u3-reading-s3"},{"en":"Misha was sad, but she kept playing music.","zh":"Misha 很难过，但仍然继续演奏。","note":"kept playing：继续演奏。","id":"u3-reading-s4"},{"en":"Two weeks later, she played for shoppers in the town centre.","zh":"两周后，她在市中心为购物的人演奏。","note":"two weeks later：两周以后。","id":"u3-reading-s5"},{"en":"A record producer called Don Parsons stopped and listened.","zh":"一位名叫 Don Parsons 的唱片制作人停下来听。","note":"record producer：唱片制作人。","id":"u3-reading-s6"},{"en":"He valued her singing and playing and offered to help her.","zh":"他欣赏她的歌唱和演奏能力，并提出帮助她。","note":"valued：重视、欣赏。","id":"u3-reading-s7"}],"questions":[{"prompt":"被拒绝后，Misha 怎么做？","options":["放弃演奏并卖掉吉他。","继续演奏音乐。","马上加入了拒绝她的两个乐队。"],"answer":1,"why":"第五、六句说明她仍然演奏。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"故事更支持哪种看法？","options":["会制造很大声音就一定有音乐能力。","外表是唯一重要的事情。","坚持练习与真实的能力值得重视。"],"answer":2,"why":"制作人看重她的歌唱和演奏，而不是前面乐队设定的外表与音量条件。","kind":"meaning","id":"u3-reading-q1"}]},"world":{"title":"Making a rhythm","pages":[42,43],"kind":"依据课文的教学改写","summary":"节奏由声音与停顿的组合产生。通过拍手、说词和音符长短，把节奏看成可重复的模式。","sentences":[{"en":"We can hear rhythms in many everyday sounds.","zh":"我们能在许多日常声音中听到节奏。","note":"everyday：日常的。","id":"u3-world-s0"},{"en":"A bouncing ball or falling rain can make a pattern of sounds.","zh":"弹跳的球或落下的雨能形成声音模式。","note":"pattern：模式。","id":"u3-world-s1"},{"en":"Music uses sounds and silences to create rhythm.","zh":"音乐利用声音和停顿创造节奏。","note":"silences 在这里表示无声的间隔。","id":"u3-world-s2"},{"en":"Some sounds are long, and others are short.","zh":"有些声音长，有些声音短。","note":"others：其他一些。","id":"u3-world-s3"},{"en":"A repeating pattern helps us hear the rhythm.","zh":"重复的模式有助于我们听出节奏。","note":"repeating：反复的。","id":"u3-world-s4"},{"en":"In this exercise, a crotchet lasts one beat and a quaver lasts half a beat.","zh":"在这个练习里，四分音符是一拍，八分音符是半拍。","note":"教材以四分音符为一拍来练习。","id":"u3-world-s5"},{"en":"Two quavers therefore last as long as one crotchet.","zh":"因此，两个八分音符与一个四分音符一样长。","note":"therefore：因此。","id":"u3-world-s6"}],"questions":[{"prompt":"音乐节奏只由声音构成吗？","options":["不是，还包括停顿。","是，停顿完全没有作用。","只需要声音足够大就能产生节奏。"],"answer":0,"why":"第三句说 sounds and silences。","kind":"meaning","id":"u3-world-q0"},{"prompt":"在本练习中，两个 quavers 一共多长？","options":["半拍。","两拍。","一拍。"],"answer":2,"why":"一个 quaver 是半拍，两个加起来是一拍。","kind":"meaning","id":"u3-world-q1"}]},"create":{"title":"我的一分钟音乐介绍","pages":[43,44,45],"tasks":["选择一位熟悉的音乐人或一段喜欢的音乐，只用自己能核对的信息。","写出喜欢的两个原因和两个 going to 练习计划。","加一句具体钟点，练习 45–60 秒介绍，并拍出一小段节奏。"],"frame":"I like ...\nI enjoy it because ...\nAt ... I’m going to ...\nNext week I’m going to ...\nThe rhythm sounds ...","model":"I like guitar music because it can be gentle or lively. I enjoy listening to clear rhythms. At half past five, I’m going to practise a short tune. Next week, I’m going to play it for my family. I can clap the rhythm before I play.","success":"能说出喜欢的原因、两项计划和一个准确钟点；音乐介绍不能只背名词清单。","teacher":"依据 p43 节奏练习、p44 展示和 p45 有顺序地写作目标新编；不编造歌手最新资料。"},"extra":[],"questions":[{"prompt":"She ___ going to play the guitar.","options":["am","is","are"],"answer":1,"why":"She 配 is。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"Are you going to ___ a new song?","options":["write","wrote","writing"],"answer":0,"why":"going to 后面接动词原形 write。","kind":"grammar","id":"u3-g0-q1"},{"prompt":"twenty to six 是几点？","options":["6:20","5:20","5:40"],"answer":2,"why":"距六点还差二十分钟，所以是 5:40。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"5:15 应该怎么说？","options":["a quarter past five","a quarter to five","half past five"],"answer":0,"why":"过五点十五分钟，用 a quarter past five。","kind":"grammar","id":"u3-g1-q1"},{"prompt":"Elvis 为什么不理解 Patrick 提到的 CD？","options":["在这个故事所处的年代，CD 对他很陌生。","他以为 Patrick 在谈自己的新演出。","他正在向 Patrick 解释如何播放 CD。"],"answer":0,"why":"时间旅行让 Patrick 用了 Elvis 所处年代不熟悉的词。","kind":"meaning","id":"u3-story-q0"},{"prompt":"真正的 Elvis 从哪里离开剧院？","options":["后门，独自一人。","前门，和 Phoebe 一起。","后门，和 Alex 一起。"],"answer":1,"why":"第八句明确说明 front door with Phoebe。","kind":"meaning","id":"u3-story-q1"},{"prompt":"被拒绝后，Misha 怎么做？","options":["放弃演奏并卖掉吉他。","继续演奏音乐。","马上加入了拒绝她的两个乐队。"],"answer":1,"why":"第五、六句说明她仍然演奏。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"故事更支持哪种看法？","options":["会制造很大声音就一定有音乐能力。","外表是唯一重要的事情。","坚持练习与真实的能力值得重视。"],"answer":2,"why":"制作人看重她的歌唱和演奏，而不是前面乐队设定的外表与音量条件。","kind":"meaning","id":"u3-reading-q1"},{"prompt":"音乐节奏只由声音构成吗？","options":["不是，还包括停顿。","是，停顿完全没有作用。","只需要声音足够大就能产生节奏。"],"answer":0,"why":"第三句说 sounds and silences。","kind":"meaning","id":"u3-world-q0"},{"prompt":"在本练习中，两个 quavers 一共多长？","options":["半拍。","两拍。","一拍。"],"answer":2,"why":"一个 quaver 是半拍，两个加起来是一拍。","kind":"meaning","id":"u3-world-q1"},{"prompt":"哪个词和 roll 的元音相同？","options":["sock","home","rock"],"answer":1,"why":"roll 与 home 通常都有 /əʊ/（美式常为 /oʊ/）。","kind":"phonics","id":"u3-ph-q0"}]},{"id":4,"title":"Space restaurant","zh":"太空餐厅","start":46,"end":57,"icon":"🍽️","goal":"读日期、解释 if 规律；按上菜顺序复述生日餐。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":122,"vocab":[{"word":"waiter","zh":"服务员","example":"The waiter brings the menu."},{"word":"biscuits","zh":"饼干","example":"There are two biscuits on the plate."},{"word":"salt","zh":"盐","example":"The salt is next to the pepper."},{"word":"pepper","zh":"胡椒","example":"Please pass the pepper."},{"word":"napkin","zh":"餐巾","example":"My napkin is on my knees."},{"word":"chopsticks","zh":"筷子","example":"I can use chopsticks."},{"word":"fork","zh":"餐叉","example":"There is a fork beside my plate."},{"word":"spoon","zh":"勺子","example":"I eat soup with a spoon."},{"word":"knife","zh":"餐刀","example":"The knife is next to the fork."}],"grammar":[{"title":"序数词与日期","rule":"日期用序数词，如 first、second、third、twenty-first。可以读 the third of April。","examples":[{"en":"My birthday is on the third of April.","zh":"我的生日是四月三日。"},{"en":"The party is on the twenty-first of May.","zh":"聚会在五月二十一日。"}],"questions":[{"prompt":"2nd 应该读作什么？","options":["two","twice","second"],"answer":2,"why":"2nd 是序数词 second，表示第二。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"the eighth of April 是哪一天？","options":["4月8日","8月4日","4月18日"],"answer":0,"why":"月份 April 是四月，eighth 是第八。","kind":"grammar","id":"u4-g0-q1"}]},{"title":"if：说明一般规律","rule":"if 从句和主句都可用一般现在时，表示通常成立的条件与结果；故事里的食物药丸是想象设定。","examples":[{"en":"If you add honey, the drink becomes sweet.","zh":"如果加入蜂蜜，饮料就变甜。"},{"en":"If ice gets warm enough, it melts.","zh":"冰足够暖时会融化。"}],"questions":[{"prompt":"If you add honey, the tea ___ sweet.","options":["become","becomes","becoming"],"answer":1,"why":"tea 为单数/不可数，谓语用 becomes。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"哪一句是在说一般规律？","options":["If water freezes, it turns into ice.","I ate soup yesterday.","Are you going to sing?"],"answer":0,"why":"if + 一般现在时说明通常的条件和结果。","kind":"grammar","id":"u4-g1-q1"}]}],"song":{"title":"功能对话：Birthday plans","page":48,"task":["用正确日期询问搭档的生日。","说出一个庆祝计划和一种礼物。","交换角色，再追问邀请几位朋友。"]},"phonics":{"title":"日期中的 th","note":"本单元功能对话没有独立歌曲拼读栏；以下依据 p47–48 日期目标新编。部分序数词 th 的声音是 /θ/。","pairs":[{"a":"four","b":"fourth"},{"a":"six","b":"sixth"},{"a":"ten","b":"tenth"}],"page":47,"questions":[{"prompt":"哪个词是 ten 的序数词？","options":["tenth","thirty","third"],"answer":0,"why":"ten 的序数词是 tenth，结尾有 th。","kind":"phonics","id":"u4-ph-q0"}]},"story":{"title":"The birthday meal","pages":[50,51],"kind":"依据课文的教学改写","summary":"Phoebe 在未来餐厅过生日。汤、主菜、甜点都很奇特；孩子们吃饱后才发现没有这种世界的钱，最后在厨房门边遇见时空门。","sentences":[{"en":"The children sat down for a birthday meal in a strange restaurant.","zh":"孩子们坐下来，在一家奇怪的餐厅吃生日餐。","note":"birthday meal：生日餐。","id":"u4-story-s0"},{"en":"The waiter brought orange soup, but it was hard instead of liquid.","zh":"服务员端来橙色的汤，但它是硬的，不是液体。","note":"instead of：而不是。","id":"u4-story-s1"},{"en":"In this imaginary restaurant, the soup broke into little balls.","zh":"在这家想象中的餐厅里，汤碎成了小球。","note":"imaginary 提醒读者这是虚构食物。","id":"u4-story-s2"},{"en":"The children used chopsticks to pick up the balls.","zh":"孩子们用筷子夹起这些小球。","note":"pick up：夹起、拿起。","id":"u4-story-s3"},{"en":"For the next course, the waiter brought coloured steam in pots.","zh":"下一道菜，服务员端来了装在锅里的彩色蒸汽。","note":"course：一道菜。","id":"u4-story-s4"},{"en":"The friends tried to eat the steam, but they were still hungry.","zh":"朋友们试着吃蒸汽，但仍然很饿。","note":"but 表示愿望没有实现。","id":"u4-story-s5"},{"en":"Then a chocolate spaceship arrived with many birthday candles.","zh":"接着，一艘插着许多生日蜡烛的巧克力飞船来了。","note":"spaceship：宇宙飞船。","id":"u4-story-s6"},{"en":"There was ice cream inside, and the children finally ate enough.","zh":"里面有冰激凌，孩子们终于吃饱了。","note":"finally：终于。","id":"u4-story-s7"},{"en":"The bill was 60,000 goldstars, but they had none of that money.","zh":"账单是六万 goldstars，但他们没有这种钱。","note":"goldstars 是故事中的货币。","id":"u4-story-s8"},{"en":"As they went towards the kitchen to work, the yellow gate appeared by the door.","zh":"他们朝厨房走去准备干活时，门边出现了黄色时空门。","note":"交代离开餐厅的转折。","id":"u4-story-s9"}],"questions":[{"prompt":"这顿饭的正确顺序是什么？","options":["飞船甜点—蒸汽—汤。","蒸汽—汤—飞船甜点。","汤—蒸汽—飞船甜点。"],"answer":2,"why":"第三道菜是带冰激凌的巧克力飞船甜点。","kind":"meaning","id":"u4-story-q0"},{"prompt":"为什么服务员要孩子们去厨房工作？","options":["他们没有 goldstars 支付账单。","他们主动报名学习做生日蛋糕。","他们已经答应在餐厅工作一周再吃饭。"],"answer":0,"why":"第九句说明无法支付，随后他们被安排去厨房。","kind":"meaning","id":"u4-story-q1"}]},"reading":{"title":"Willy Wonka’s imagined inventions","pages":[52],"kind":"依据课文的教学改写","summary":"教材博客介绍 Willy Wonka 故事世界里的奇妙糖果。分清“作者想象的发明”和现实食物，再用 if 描述自己设计的虚构发明。","sentences":[{"en":"The blog describes sweets from Willy Wonka's imaginary world.","zh":"博客介绍了 Willy Wonka 想象世界里的糖果。","note":"不是现实商品说明。","id":"u4-reading-s0"},{"en":"One piece of chewing gum can become a whole three-course meal.","zh":"一块口香糖可以变成一整套三道菜。","note":"whole：完整的。","id":"u4-reading-s1"},{"en":"The meal begins with soup and ends with a dessert.","zh":"这顿饭从汤开始，以甜点结束。","note":"begins with / ends with：以……开始/结束。","id":"u4-reading-s2"},{"en":"Another invention is ice cream that does not melt.","zh":"另一项发明是不会融化的冰激凌。","note":"does not melt：不融化。","id":"u4-reading-s3"},{"en":"The writer also describes wallpaper that tastes like fruit.","zh":"作者还描写了有水果味的墙纸。","note":"wallpaper：墙纸。","id":"u4-reading-s4"},{"en":"There are lollipops with lights, like tiny lamps.","zh":"还有带灯的棒棒糖，像小小的灯一样。","note":"like 表示比较。","id":"u4-reading-s5"},{"en":"A kind of sugar grass grows near a chocolate river in the story.","zh":"故事里，一种糖做的草长在巧克力河附近。","note":"in the story 限定虚构世界。","id":"u4-reading-s6"},{"en":"The blogger invites readers to imagine flavours and choose a favourite invention.","zh":"博主邀请读者想象味道，并选择喜欢的发明。","note":"flavours：味道。","id":"u4-reading-s7"}],"questions":[{"prompt":"这里的不会融化的冰激凌属于什么？","options":["经过本文验证的现实发明。","故事中的想象发明。","实际制作冰激凌的操作步骤。"],"answer":1,"why":"开头说明是 imaginary world。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"three-course meal 最接近什么意思？","options":["三道菜的一顿饭。","三个人合吃的一道菜。","三天吃完的一顿饭。"],"answer":0,"why":"课文举出开头的汤和结尾的甜点，course 在这里是菜的道数。","kind":"meaning","id":"u4-reading-q1"}]},"world":{"title":"Different foods, different jobs","pages":[54,55],"kind":"依据课文的教学改写","summary":"学习食物分类和身体需要食物的原因。这里是语言与科学概念练习，不给孩子规定个人饮食份量。","sentences":[{"en":"Our bodies need food for energy and growth.","zh":"身体需要食物来获取能量并生长。","note":"energy：能量；growth：生长。","id":"u4-world-s0"},{"en":"Different foods provide different nutrients.","zh":"不同食物提供不同营养成分。","note":"nutrients：营养成分。","id":"u4-world-s1"},{"en":"The book groups foods into fruit and vegetables, grains, dairy products, proteins and sugars.","zh":"教材把食物分成果蔬、谷物、乳制品、蛋白质类和糖类。","note":"这是本页采用的分类标签。","id":"u4-world-s2"},{"en":"Grains include foods such as bread and rice.","zh":"谷物类包括面包和米饭等食物。","note":"such as：例如。","id":"u4-world-s3"},{"en":"Milk and cheese are examples of dairy products.","zh":"牛奶和奶酪是乳制品的例子。","note":"dairy products：乳制品。","id":"u4-world-s4"},{"en":"Protein helps the body grow and repair itself.","zh":"蛋白质帮助身体生长和修复。","note":"repair：修复。","id":"u4-world-s5"},{"en":"A food diary helps us notice the variety of foods we eat.","zh":"食物日记帮助我们注意自己吃的食物是否多样。","note":"variety：多样性；不需要评判体形。","id":"u4-world-s6"}],"questions":[{"prompt":"按文中分类，牛奶属于哪一类？","options":["谷物。","乳制品。","水果。"],"answer":1,"why":"第五句给出 milk and cheese 是 dairy products。","kind":"meaning","id":"u4-world-q0"},{"prompt":"food diary 可以帮助我们观察什么？","options":["食物的多样性。","未来一周食物的准确价格。","每家餐厅的完整菜单。"],"answer":0,"why":"最后一句写出食物日记的用途。","kind":"meaning","id":"u4-world-q1"}]},"create":{"title":"我的未来餐厅菜单","pages":[48,49,53,56,57],"tasks":["画一份虚构菜单，列出前菜、主菜和甜点并给出价格。","用日期邀请朋友，再用两句 if 描述食物的想象规则。","扮演服务员和顾客，问菜单、点餐、核对总价。"],"frame":"The meal is on the ... of ...\nFor starters, I’d like ...\nIf you ..., it ...\nThe main course is ...\nCould I have the bill, please?\nThe total is ...","model":"My imaginary restaurant opens on the third of May. For starters, I’d like moon soup. If you tap the bowl in my story, the soup turns blue. The main course is star rice, and dessert is cloud ice cream. Could I have the bill, please? The total is twenty stars.","success":"能读准日期、按三道菜顺序介绍、用 if 表达规则，并核对虚构价格。","teacher":"依据 p48 生日对话、p49 if 规则、p53 食物发明及 p56–57 点餐写作目标新编；菜单无需制作成真实食品。"},"extra":[],"questions":[{"prompt":"2nd 应该读作什么？","options":["two","twice","second"],"answer":2,"why":"2nd 是序数词 second，表示第二。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"the eighth of April 是哪一天？","options":["4月8日","8月4日","4月18日"],"answer":0,"why":"月份 April 是四月，eighth 是第八。","kind":"grammar","id":"u4-g0-q1"},{"prompt":"If you add honey, the tea ___ sweet.","options":["become","becomes","becoming"],"answer":1,"why":"tea 为单数/不可数，谓语用 becomes。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"哪一句是在说一般规律？","options":["If water freezes, it turns into ice.","I ate soup yesterday.","Are you going to sing?"],"answer":0,"why":"if + 一般现在时说明通常的条件和结果。","kind":"grammar","id":"u4-g1-q1"},{"prompt":"这顿饭的正确顺序是什么？","options":["飞船甜点—蒸汽—汤。","蒸汽—汤—飞船甜点。","汤—蒸汽—飞船甜点。"],"answer":2,"why":"第三道菜是带冰激凌的巧克力飞船甜点。","kind":"meaning","id":"u4-story-q0"},{"prompt":"为什么服务员要孩子们去厨房工作？","options":["他们没有 goldstars 支付账单。","他们主动报名学习做生日蛋糕。","他们已经答应在餐厅工作一周再吃饭。"],"answer":0,"why":"第九句说明无法支付，随后他们被安排去厨房。","kind":"meaning","id":"u4-story-q1"},{"prompt":"这里的不会融化的冰激凌属于什么？","options":["经过本文验证的现实发明。","故事中的想象发明。","实际制作冰激凌的操作步骤。"],"answer":1,"why":"开头说明是 imaginary world。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"three-course meal 最接近什么意思？","options":["三道菜的一顿饭。","三个人合吃的一道菜。","三天吃完的一顿饭。"],"answer":0,"why":"课文举出开头的汤和结尾的甜点，course 在这里是菜的道数。","kind":"meaning","id":"u4-reading-q1"},{"prompt":"按文中分类，牛奶属于哪一类？","options":["谷物。","乳制品。","水果。"],"answer":1,"why":"第五句给出 milk and cheese 是 dairy products。","kind":"meaning","id":"u4-world-q0"},{"prompt":"food diary 可以帮助我们观察什么？","options":["食物的多样性。","未来一周食物的准确价格。","每家餐厅的完整菜单。"],"answer":0,"why":"最后一句写出食物日记的用途。","kind":"meaning","id":"u4-world-q1"},{"prompt":"哪个词是 ten 的序数词？","options":["tenth","thirty","third"],"answer":0,"why":"ten 的序数词是 tenth，结尾有 th。","kind":"phonics","id":"u4-ph-q0"}]},{"id":5,"title":"The Wild West","zh":"西部历险","start":58,"end":69,"icon":"🤠","goal":"说清材料和用途；区分一个人与多个人的所有格。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":123,"vocab":[{"word":"jail","zh":"监狱","example":"The jail is in the old town."},{"word":"sheriff","zh":"警长","example":"The sheriff wears a badge."},{"word":"robber","zh":"劫匪","example":"The robber appears in the story."},{"word":"wagon","zh":"四轮运货马车","example":"The wagon carries boxes."},{"word":"handcuffs","zh":"手铐","example":"The sheriff has a pair of handcuffs."},{"word":"barrel","zh":"桶","example":"There is a wooden barrel outside."},{"word":"pistol","zh":"手枪","example":"The pistol is a dangerous weapon in the story."},{"word":"saddle","zh":"马鞍","example":"The saddle is on the horse."},{"word":"rope","zh":"绳子","example":"The rope is made of strong fibres."}],"grammar":[{"title":"材料与用途","rule":"be made of + 材料；be used for + 名词或动词-ing。注意 of 与 for。","examples":[{"en":"The saddle is made of leather.","zh":"马鞍是皮革做的。"},{"en":"A cup is used for drinking.","zh":"杯子用来喝东西。"}],"questions":[{"prompt":"The barrel is made ___ wood.","options":["for","of","to"],"answer":1,"why":"材料用 made of。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"This bag is used for ___ books.","options":["carry","carried","carrying"],"answer":2,"why":"介词 for 后跟动词-ing：carrying。","kind":"grammar","id":"u5-g0-q1"}]},{"title":"名词所有格","rule":"一个人通常加 ’s；以 s 结尾的规则复数只加 ’；children 等不规则复数加 ’s。","examples":[{"en":"The sheriff’s badge is silver.","zh":"这位警长的徽章是银色的。"},{"en":"The children’s hats are brown.","zh":"孩子们的帽子是棕色的。"}],"questions":[{"prompt":"表示“两个婴儿的帽子”应选哪一个？","options":["the baby’s hats","the babies’ hats","the baby hats’s"],"answer":1,"why":"babies 已是以 s 结尾的复数，在末尾加撇号。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"表示“孩子们的书”应选哪一个？","options":["the childrens’ books","the children books’","the children’s books"],"answer":2,"why":"children 是不以 s 结尾的复数，要加 ’s。","kind":"grammar","id":"u5-g1-q1"}]}],"song":{"title":"歌曲：The meanest robber in town","page":60,"task":["区分故事人物 sheriff 和 robber。","找出歌曲中的过去式；不猜缺失的原版音轨答案。","用 made of 描述一个安全的日常物品。"]},"phonics":{"title":"双写辅音：拼写与发音","note":"对应 p60 double consonants；双写字母通常不需要把声音读两遍，比较词形。","pairs":[{"a":"run","b":"running"},{"a":"rob","b":"robber"},{"a":"big","b":"bigger"}],"page":60,"questions":[{"prompt":"run 加 -ing 的正确拼写是？","options":["runing","running","runeing"],"answer":1,"why":"run 加 -ing 时双写 n：running。","kind":"phonics","id":"u5-ph-q0"}]},"story":{"title":"The bank robbery","pages":[62,63],"kind":"依据课文的教学改写","summary":"孩子们看到银行抢劫，先找警长。故事里他们用冒险办法拖住劫匪，警长最终逮捕了他们。下面只理解虚构情节；遇到现实危险应远离并求助。","sentences":[{"en":"The children saw men with covered faces enter the bank.","zh":"孩子们看见几个遮着脸的男人走进银行。","note":"covered faces：遮住的脸。","id":"u5-story-s0"},{"en":"A woman ran out and shouted that the bank was being robbed.","zh":"一位女士跑出来，喊着银行正在遭抢劫。","note":"ran out：跑出来。","id":"u5-story-s1"},{"en":"Phoebe said it was too dangerous to go inside, so they went to the sheriff.","zh":"Phoebe 说进去太危险，因此他们去找警长。","note":"too dangerous：太危险。","id":"u5-story-s2"},{"en":"The sheriff was afraid because the men were the Dalton brothers.","zh":"警长很害怕，因为那些人是 Dalton 兄弟。","note":"because 解释警长为什么不愿行动。","id":"u5-story-s3"},{"en":"In the story, Patrick used a rope to delay the robbers' escape.","zh":"故事中，Patrick 用绳子试图拖延劫匪逃跑。","note":"概括情节，不把危险行动做成操作任务。","id":"u5-story-s4"},{"en":"Alex secretly damaged the straps on their saddles.","zh":"Alex 悄悄弄坏了他们马鞍上的带子。","note":"secretly：悄悄地；只复述虚构故事。","id":"u5-story-s5"},{"en":"The robbers freed their horses and rode away.","zh":"劫匪解开了马匹的束缚，骑马离开。","note":"freed：释放、解开束缚。","id":"u5-story-s6"},{"en":"When the horses jumped a fence, the robbers fell to the ground.","zh":"当马跳过篱笆时，劫匪摔到了地上。","note":"when 连接同时发生的转折。","id":"u5-story-s7"},{"en":"The sheriff arrested them and gave the children badges.","zh":"警长逮捕了他们，并给孩子们徽章。","note":"arrested：逮捕。","id":"u5-story-s8"},{"en":"Then the yellow gate appeared, and the Time Travellers left the town.","zh":"随后黄色门出现，时间旅行者们离开了小镇。","note":"故事离开这一站。","id":"u5-story-s9"}],"questions":[{"prompt":"警长起初为什么没有采取行动？","options":["他认为银行没有发生任何事情。","他已在另一条街抓住了劫匪。","他害怕 Dalton 兄弟。"],"answer":2,"why":"第四句说 sheriff was afraid。","kind":"meaning","id":"u5-story-q0"},{"prompt":"故事中，最后是谁逮捕劫匪？","options":["警长。","Patrick。","Alex。"],"answer":0,"why":"第九句明确写出 The sheriff arrested them。","kind":"meaning","id":"u5-story-q1"}]},"reading":{"title":"Different peoples, different traditions","pages":[64,65],"kind":"依据课文的教学改写","summary":"原页标题使用 American Indians。这里采用“北美原住民”说明不同社群有不同语言、家园和传统，不把所有人描绘成同一种生活方式。","sentences":[{"en":"The text introduces some Indigenous peoples of North America.","zh":"文章介绍了北美的一些原住民社群。","note":"Indigenous peoples：原住民各族群。","id":"u5-reading-s0"},{"en":"It uses the older term American Indians in its title.","zh":"标题使用了较旧的称呼 American Indians。","note":"读原页时认识这个词，同时理解称呼的语境。","id":"u5-reading-s1"},{"en":"There were many different communities, with different languages.","zh":"那里有许多不同社群，使用不同的语言。","note":"communities：社群。","id":"u5-reading-s2"},{"en":"Their homes and ways of life were not all the same.","zh":"他们的家园与生活方式并不都一样。","note":"not all the same：并非完全相同。","id":"u5-reading-s3"},{"en":"Some communities used tall tents called teepees.","zh":"有些社群使用叫 teepees 的高帐篷。","note":"some 表示部分，不能改成 all。","id":"u5-reading-s4"},{"en":"Bison were important to some Plains peoples for food and materials.","zh":"对一些大平原族群而言，野牛是重要的食物和材料来源。","note":"不把这一特点套用到所有北美原住民。","id":"u5-reading-s5"},{"en":"The reading describes conflict when newcomers wanted their land.","zh":"阅读描述了外来者想占用他们土地时发生的冲突。","note":"conflict：冲突。","id":"u5-reading-s6"},{"en":"It reminds us that history, languages and traditions deserve respect.","zh":"文章提醒我们，历史、语言和传统都值得尊重。","note":"deserve respect：值得尊重。","id":"u5-reading-s7"}],"questions":[{"prompt":"哪一句准确保留了文章中“多样性”的意思？","options":["所有社群使用同一种语言。","所有人都住相同的帐篷。","不同社群有不同语言与生活方式。"],"answer":2,"why":"第三、第四句明确强调差异。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"some communities 应该理解为？","options":["一些社群。","每一个社群。","没有任何社群。"],"answer":0,"why":"some 是一部分，不等于 all。","kind":"meaning","id":"u5-reading-q1"}]},"world":{"title":"Gold: material and uses","pages":[66,67],"kind":"依据课文的教学改写","summary":"用材料、开采难度和用途理解黄金。本节保留稳定概念，不提供价格、投资建议或旧教材中的产量排名。","sentences":[{"en":"Gold is a precious metal.","zh":"黄金是一种贵金属。","note":"precious：珍贵的。","id":"u5-world-s0"},{"en":"Small pieces may be found in streams, but much gold is underground.","zh":"小块黄金可能在溪流里发现，但很多黄金在地下。","note":"underground：在地下。","id":"u5-world-s1"},{"en":"Mines and machines are used to bring it to the surface.","zh":"矿井和机器被用来把它带到地表。","note":"are used to：被用于。","id":"u5-world-s2"},{"en":"Finding and extracting gold can be difficult.","zh":"寻找和提取黄金可能很困难。","note":"extracting：提取。","id":"u5-world-s3"},{"en":"Gold is rare, which helps explain why people value it.","zh":"黄金较稀有，这有助于解释人们为何珍视它。","note":"rare：稀有的；不表示价格永远上涨。","id":"u5-world-s4"},{"en":"It can be shaped into jewellery such as rings.","zh":"它可以制成戒指等珠宝。","note":"such as：例如。","id":"u5-world-s5"},{"en":"Gold also conducts electricity, so it is used in some electronic parts.","zh":"黄金也能导电，因此用在某些电子部件中。","note":"conducts electricity：导电。","id":"u5-world-s6"}],"questions":[{"prompt":"文章提到黄金被珍视的一个原因是什么？","options":["开采它总是很容易。","它较稀有。","它比普通石头更常见。"],"answer":1,"why":"第五句把 rare 和 value 联系起来。","kind":"meaning","id":"u5-world-q0"},{"prompt":"黄金为什么能用于某些电子部件？","options":["因为它能阻断所有电流。","因为它具有与塑料相同的绝缘作用。","因为它能导电。"],"answer":2,"why":"最后一句说明 conducts electricity。","kind":"meaning","id":"u5-world-q1"}]},"create":{"title":"安全的西部故事展板","pages":[59,61,68,69],"tasks":["画一个完全虚构的小镇人物，不使用现实同学的通缉照片。","用 made of、used for 描述两个日常物品，再写一组单数与复数所有格。","写 6–8 句有开头、问题、求助和结尾的小故事，加入一句人物对话。"],"frame":"My character is ...\nThe ... is made of ...\nIt is used for ...\nOne day, ...\n“...,” ... said.\nThey asked ... for help.\nIn the end, ...","model":"My character is a helpful sheriff. Her hat is made of cotton. Her notebook is used for writing clues. One day, a visitor lost a bag. “Can you help me?” he asked. The sheriff asked the shopkeepers. In the end, they found the visitor’s bag beside the wagon.","success":"材料与用途表达正确；能用所有格说明“谁的”；故事以观察与求助解决问题。","teacher":"依据 p68 人物海报和 p69 故事写作改编为安全的失物故事；不要求儿童表演攻击、追捕或武器操作。"},"extra":[],"questions":[{"prompt":"The barrel is made ___ wood.","options":["for","of","to"],"answer":1,"why":"材料用 made of。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"This bag is used for ___ books.","options":["carry","carried","carrying"],"answer":2,"why":"介词 for 后跟动词-ing：carrying。","kind":"grammar","id":"u5-g0-q1"},{"prompt":"表示“两个婴儿的帽子”应选哪一个？","options":["the baby’s hats","the babies’ hats","the baby hats’s"],"answer":1,"why":"babies 已是以 s 结尾的复数，在末尾加撇号。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"表示“孩子们的书”应选哪一个？","options":["the childrens’ books","the children books’","the children’s books"],"answer":2,"why":"children 是不以 s 结尾的复数，要加 ’s。","kind":"grammar","id":"u5-g1-q1"},{"prompt":"警长起初为什么没有采取行动？","options":["他认为银行没有发生任何事情。","他已在另一条街抓住了劫匪。","他害怕 Dalton 兄弟。"],"answer":2,"why":"第四句说 sheriff was afraid。","kind":"meaning","id":"u5-story-q0"},{"prompt":"故事中，最后是谁逮捕劫匪？","options":["警长。","Patrick。","Alex。"],"answer":0,"why":"第九句明确写出 The sheriff arrested them。","kind":"meaning","id":"u5-story-q1"},{"prompt":"哪一句准确保留了文章中“多样性”的意思？","options":["所有社群使用同一种语言。","所有人都住相同的帐篷。","不同社群有不同语言与生活方式。"],"answer":2,"why":"第三、第四句明确强调差异。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"some communities 应该理解为？","options":["一些社群。","每一个社群。","没有任何社群。"],"answer":0,"why":"some 是一部分，不等于 all。","kind":"meaning","id":"u5-reading-q1"},{"prompt":"文章提到黄金被珍视的一个原因是什么？","options":["开采它总是很容易。","它较稀有。","它比普通石头更常见。"],"answer":1,"why":"第五句把 rare 和 value 联系起来。","kind":"meaning","id":"u5-world-q0"},{"prompt":"黄金为什么能用于某些电子部件？","options":["因为它能阻断所有电流。","因为它具有与塑料相同的绝缘作用。","因为它能导电。"],"answer":2,"why":"最后一句说明 conducts electricity。","kind":"meaning","id":"u5-world-q1"},{"prompt":"run 加 -ing 的正确拼写是？","options":["runing","running","runeing"],"answer":1,"why":"run 加 -ing 时双写 n：running。","kind":"phonics","id":"u5-ph-q0"}]},{"id":6,"title":"In Istanbul","zh":"伊斯坦布尔之旅","start":70,"end":81,"icon":"🕌","goal":"用 should 提建议，用 Could I 礼貌请求；讲清走散与重聚。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":124,"vocab":[{"word":"flag","zh":"旗帜","example":"The flag flies above the building."},{"word":"sunglasses","zh":"太阳镜","example":"Her sunglasses are in the bag."},{"word":"earrings","zh":"耳环","example":"The earrings are in a small box."},{"word":"carpet","zh":"地毯","example":"The carpet has a colourful pattern."},{"word":"basket","zh":"篮子","example":"We put the gifts in a basket."},{"word":"rings","zh":"戒指","example":"The rings are on display."},{"word":"cup and saucer","zh":"杯子和茶碟","example":"This cup and saucer are blue."},{"word":"cushion","zh":"靠垫","example":"The cushion is soft."},{"word":"plate","zh":"盘子","example":"The plate is made of clay."},{"word":"comb","zh":"梳子","example":"I keep a comb in my bag."}],"grammar":[{"title":"should / shouldn’t：建议","rule":"should + 动词原形表示应该；shouldn’t 表示不应该。它比 must 更侧重建议。","examples":[{"en":"You should take a map.","zh":"你应该带地图。"},{"en":"You shouldn’t take photos without asking.","zh":"没有先询问，不应该拍照。"}],"questions":[{"prompt":"You ___ ask before taking a photograph of someone.","options":["should","shouldn’t","did"],"answer":0,"why":"尊重别人，拍照前应先问许可。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"After should, which form is correct?","options":["takes","taking","take"],"answer":2,"why":"情态动词 should 后用动词原形。","kind":"grammar","id":"u6-g0-q1"}]},{"title":"礼貌请求与询问许可","rule":"Could I ...? 询问我能否做；Could you ...? 请别人做；Do you mind if ...? 的 Not at all 表示不介意。","examples":[{"en":"Could I see that cup, please?","zh":"我可以看看那个杯子吗？"},{"en":"Do you mind if I sit here? — Not at all.","zh":"你介意我坐这里吗？——不介意。"}],"questions":[{"prompt":"想请店员展示一顶帽子，应说：","options":["Could you show me that hat, please?","You hat me show.","I showed a hat yesterday."],"answer":0,"why":"Could you + 动词原形是礼貌请求。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"“Do you mind if I open the book?” 回答 “Not at all.” 意思是？","options":["绝对不能打开。","不介意，可以打开。","书已经丢了。"],"answer":1,"why":"Not at all 在这里表示一点也不介意。","kind":"grammar","id":"u6-g1-q1"}]}],"song":{"title":"功能对话：Disagreeing politely","page":72,"task":["两人分别推荐一种给老师的礼物。","用 I’m not so sure 或 I don’t agree 礼貌表达不同意见。","读出价格后，商量共同选择。"]},"phonics":{"title":"礼貌提问中的重读","note":"本单元 p72 是功能对话；这里依据 p73 新编朗读训练，把请求的关键动作读清。","pairs":[{"a":"Could I see it?","b":"Could I try it on?"},{"a":"Could you help me?","b":"Could you show me?"},{"a":"Not at all.","b":"Of course."}],"page":73,"questions":[{"prompt":"想询问是否可以试穿，应把哪个短语读清？","options":["try it on","turn it off","eat it up"],"answer":0,"why":"try it on 表示试穿，是这个请求的关键动作。","kind":"phonics","id":"u6-ph-q0"}]},"story":{"title":"Lost in the city","pages":[74,75],"kind":"依据课文的教学改写","summary":"三个孩子规划参观伊斯坦布尔，却在拥挤的地铁站走散。Ali 提醒男孩们回到最后见到 Phoebe 的地方，他们才终于重聚。","sentences":[{"en":"Phoebe bought a guidebook and showed the boys the sights of Istanbul.","zh":"Phoebe 买了一本旅行指南，向男孩们展示伊斯坦布尔的景点。","note":"guidebook：旅行指南。","id":"u6-story-s0"},{"en":"They made a list of places to visit and decided to take the underground.","zh":"他们列好想去的地点，决定乘地铁。","note":"decided to：决定。","id":"u6-story-s1"},{"en":"At busy Taksim station, Alex and Patrick got onto a train.","zh":"在繁忙的 Taksim 站，Alex 和 Patrick 上了一列地铁。","note":"got onto：登上。","id":"u6-story-s2"},{"en":"The doors closed before Phoebe could join them.","zh":"Phoebe 还没来得及跟上，门就关了。","note":"before 交代走散的先后关系。","id":"u6-story-s3"},{"en":"The boys hoped to find her at the sights on their list.","zh":"男孩们希望在清单上的景点找到她。","note":"hoped to：希望。","id":"u6-story-s4"},{"en":"They visited several places, but they did not find her.","zh":"他们去了好几个地方，却没有找到她。","note":"but 说明计划没有成功。","id":"u6-story-s5"},{"en":"A friendly boy called Ali listened to their problem.","zh":"一个叫 Ali 的友好男孩听他们讲了遇到的问题。","note":"listened to：认真听。","id":"u6-story-s6"},{"en":"He suggested returning to the station where they had last seen Phoebe.","zh":"他建议回到他们最后看见 Phoebe 的那个车站。","note":"suggested：建议。","id":"u6-story-s7"},{"en":"Phoebe was still waiting there, and the friends were happy to be together again.","zh":"Phoebe 仍在那里等候，朋友们重聚后很开心。","note":"still：仍然。","id":"u6-story-s8"},{"en":"Before Ali could show them more sights, the yellow gate appeared near the escalator.","zh":"Ali 还没来得及带他们看更多景点，黄色门就在扶梯附近出现了。","note":"故事中时间门打断了新的计划。","id":"u6-story-s9"}],"questions":[{"prompt":"孩子们在哪里走散？","options":["蓝色清真寺。","Taksim 地铁站。","香料市场。"],"answer":1,"why":"第三、第四句交代地铁车门关闭造成走散。","kind":"meaning","id":"u6-story-q0"},{"prompt":"Ali 的哪条建议帮助他们找到 Phoebe？","options":["再去全部景点一次。","换一本更大的指南。","回到最后见到她的车站。"],"answer":2,"why":"第八句是关键转折。","kind":"meaning","id":"u6-story-q1"}]},"reading":{"title":"The world in a room","pages":[76,77],"kind":"依据课文的教学改写","summary":"教材用一个示例房间说明日常用品可能来自不同国家。例子属于书中的情境，不能当成今天每个品牌或每件商品的固定产地。","sentences":[{"en":"The reading asks us to look around an example bedroom.","zh":"阅读请我们环顾一个示例卧室。","note":"an example 表明这是一个情境，不代表每个人的房间。","id":"u6-reading-s0"},{"en":"The trainers, clothes, phone and computer come from different countries in the text.","zh":"在文中，运动鞋、衣服、手机和电脑来自不同国家。","note":"come from：来自。","id":"u6-reading-s1"},{"en":"The example trainers are made in Indonesia.","zh":"示例中的运动鞋产自印度尼西亚。","note":"in the example；不是所有运动鞋都产于此。","id":"u6-reading-s2"},{"en":"The text mentions a computer from China and a car from Germany.","zh":"文中提到来自中国的电脑和来自德国的汽车。","note":"mentions：提到。","id":"u6-reading-s3"},{"en":"Even the television programmes connect the room with other places.","zh":"甚至电视节目也让这个房间与其他地方发生联系。","note":"connect ... with：把……与……联系起来。","id":"u6-reading-s4"},{"en":"We can check labels instead of guessing where an object was made.","zh":"我们可以查看标签，而不是猜物品在哪里制造。","note":"labels：标签；依据阅读目标补充的方法。","id":"u6-reading-s5"},{"en":"The next page asks where our food comes from and how far it travels.","zh":"下一页询问食物来自哪里，以及运输了多远。","note":"how far：多远。","id":"u6-reading-s6"},{"en":"Together, the pages show how everyday life is connected with the wider world.","zh":"这两页共同说明日常生活如何与更广阔的世界相联系。","note":"wider world：更广阔的世界。","id":"u6-reading-s7"}],"questions":[{"prompt":"如何确认自己一件物品的产地更可靠？","options":["直接查看物品标签。","把书中电脑的产地套到所有物品。","只凭颜色猜。"],"answer":0,"why":"第六句建议 check labels instead of guessing。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"这篇阅读的中心意思是什么？","options":["每个人房间里的东西完全一样。","日常用品把我们与世界各地联系起来。","只有旅行才能接触别的地方。"],"answer":1,"why":"最后一句总结了 connected with the wider world。","kind":"meaning","id":"u6-reading-q1"}]},"world":{"title":"Planning a town","pages":[78,79],"kind":"依据课文的教学改写","summary":"一个适合生活的小镇需要住宅、工作、交通和公共服务。规划时，要考虑不同人的需要，而不只是把建筑塞进地图。","sentences":[{"en":"Town planners think about how a town can be a good place to live.","zh":"城镇规划者思考怎样让一个城镇适合生活。","note":"town planners：城镇规划者。","id":"u6-world-s0"},{"en":"They need space for homes and places where people work.","zh":"他们需要为住宅和工作地点安排空间。","note":"space：空间。","id":"u6-world-s1"},{"en":"They consider how people will travel by foot, bus, train or car.","zh":"他们考虑人们如何步行或乘公交、火车和汽车出行。","note":"consider：考虑。","id":"u6-world-s2"},{"en":"Schools, libraries and hospitals provide important services.","zh":"学校、图书馆和医院提供重要服务。","note":"services：服务。","id":"u6-world-s3"},{"en":"Parks and playgrounds give people places to relax and play.","zh":"公园和游乐场提供休息、玩耍的场所。","note":"relax：放松。","id":"u6-world-s4"},{"en":"Different people may need different places near their homes.","zh":"不同的人可能需要不同的设施靠近住宅。","note":"different needs：不同需要。","id":"u6-world-s5"},{"en":"A useful plan explains both where a place is and why it belongs there.","zh":"有用的规划既说明地点在哪里，也说明为什么这样安排。","note":"both ... and ...：既……又……。","id":"u6-world-s6"}],"questions":[{"prompt":"哪一组设施在文中用于公共服务？","options":["私人住宅、车库、家庭花园。","学校、图书馆、医院。","货物仓库、工厂、私人办公室。"],"answer":1,"why":"第四句列出了这些服务设施。","kind":"meaning","id":"u6-world-q0"},{"prompt":"好的规划除了画地点，还需要解释什么？","options":["为什么把它安排在那里。","是否能只考虑汽车的需要。","是否让所有建筑使用同一张设计图。"],"answer":0,"why":"最后一句强调 why it belongs there。","kind":"meaning","id":"u6-world-q1"}]},"create":{"title":"给小镇游客的一份指南","pages":[73,79,80,81],"tasks":["画一张有四处地点的小镇地图，用英语标注。","写两条 should 和一条 shouldn’t 的建议，并解释原因。","扮演游客与店员，用 Could I / Could you 完成一段购物问答。"],"frame":"Welcome to ...\nYou should ... because ...\nYou shouldn’t ...\nThe ... is next to ...\nCould I ... , please?\nCould you ... ?","model":"Welcome to Green Town. You should visit the library because it has a room for children. You should bring comfortable shoes for the park. You shouldn’t leave litter. The gift shop is next to the library. Could I see that blue cup, please? Could you tell me the price?","success":"地图位置说得清楚；建议后有原因；至少完成一问一答的礼貌请求。","teacher":"依据 p79 规划项目、p80 购物角色扮演和 p81 游客建议写作新编；地图和店铺均为虚构。"},"extra":[],"questions":[{"prompt":"You ___ ask before taking a photograph of someone.","options":["should","shouldn’t","did"],"answer":0,"why":"尊重别人，拍照前应先问许可。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"After should, which form is correct?","options":["takes","taking","take"],"answer":2,"why":"情态动词 should 后用动词原形。","kind":"grammar","id":"u6-g0-q1"},{"prompt":"想请店员展示一顶帽子，应说：","options":["Could you show me that hat, please?","You hat me show.","I showed a hat yesterday."],"answer":0,"why":"Could you + 动词原形是礼貌请求。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"“Do you mind if I open the book?” 回答 “Not at all.” 意思是？","options":["绝对不能打开。","不介意，可以打开。","书已经丢了。"],"answer":1,"why":"Not at all 在这里表示一点也不介意。","kind":"grammar","id":"u6-g1-q1"},{"prompt":"孩子们在哪里走散？","options":["蓝色清真寺。","Taksim 地铁站。","香料市场。"],"answer":1,"why":"第三、第四句交代地铁车门关闭造成走散。","kind":"meaning","id":"u6-story-q0"},{"prompt":"Ali 的哪条建议帮助他们找到 Phoebe？","options":["再去全部景点一次。","换一本更大的指南。","回到最后见到她的车站。"],"answer":2,"why":"第八句是关键转折。","kind":"meaning","id":"u6-story-q1"},{"prompt":"如何确认自己一件物品的产地更可靠？","options":["直接查看物品标签。","把书中电脑的产地套到所有物品。","只凭颜色猜。"],"answer":0,"why":"第六句建议 check labels instead of guessing。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"这篇阅读的中心意思是什么？","options":["每个人房间里的东西完全一样。","日常用品把我们与世界各地联系起来。","只有旅行才能接触别的地方。"],"answer":1,"why":"最后一句总结了 connected with the wider world。","kind":"meaning","id":"u6-reading-q1"},{"prompt":"哪一组设施在文中用于公共服务？","options":["私人住宅、车库、家庭花园。","学校、图书馆、医院。","货物仓库、工厂、私人办公室。"],"answer":1,"why":"第四句列出了这些服务设施。","kind":"meaning","id":"u6-world-q0"},{"prompt":"好的规划除了画地点，还需要解释什么？","options":["为什么把它安排在那里。","是否能只考虑汽车的需要。","是否让所有建筑使用同一张设计图。"],"answer":0,"why":"最后一句强调 why it belongs there。","kind":"meaning","id":"u6-world-q1"},{"prompt":"想询问是否可以试穿，应把哪个短语读清？","options":["try it on","turn it off","eat it up"],"answer":0,"why":"try it on 表示试穿，是这个请求的关键动作。","kind":"phonics","id":"u6-ph-q0"}]},{"id":7,"title":"The story teller","zh":"故事讲述者","start":82,"end":93,"icon":"🎭","goal":"用 will 主动帮忙，用 just 说明刚发生的事；读懂线索并创作小诗。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":125,"vocab":[{"word":"audience","zh":"观众","example":"The audience claps at the end."},{"word":"candles","zh":"蜡烛","example":"The candles are on the stage in the picture."},{"word":"mask","zh":"面具","example":"The actor is wearing a mask."},{"word":"lute","zh":"鲁特琴","example":"The musician plays a lute."},{"word":"actor","zh":"演员","example":"The actor learns his lines."},{"word":"wig","zh":"假发","example":"The wig has long black hair."},{"word":"costume","zh":"戏服","example":"Her costume is green."},{"word":"lights","zh":"灯光","example":"The lights shine on the stage."}],"grammar":[{"title":"will：主动帮忙与承诺","rule":"I’ll = I will，可用于当场决定提供帮助或作出承诺；后接动词原形。","examples":[{"en":"I’ll carry your bag.","zh":"我来帮你拿包。"},{"en":"I’ll bring the costumes tomorrow.","zh":"明天我会带戏服来。"}],"questions":[{"prompt":"“你渴了？我去拿水。”应说：","options":["I’ll get some water.","I was get water.","I’ll getting water."],"answer":0,"why":"I’ll + 动词原形 get，表示现在作出的帮助决定。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"I’ll is short for ___.","options":["I had","I will","I am"],"answer":1,"why":"I’ll 是 I will 的缩写。","kind":"grammar","id":"u7-g0-q1"}]},{"title":"现在完成时 + just","rule":"have/has + just + 过去分词，表示刚刚发生、与现在有关的事。he/she 配 has。","examples":[{"en":"She has just opened the door.","zh":"她刚刚打开门。"},{"en":"They have just finished the play.","zh":"他们刚刚演完戏。"}],"questions":[{"prompt":"He ___ just read the news.","options":["have","is","has"],"answer":2,"why":"He 配 has；read 在这里是过去分词。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"“他们刚刚到达。”应说：","options":["They have just arrived.","They just arriving.","They has just arrive."],"answer":0,"why":"They 配 have，arrive 的过去分词是 arrived。","kind":"grammar","id":"u7-g1-q1"}]}],"song":{"title":"歌曲：You’ll never buy me rings","page":84,"task":["找出表达承诺的 I’ll。","用自己的话说一件能做到的小承诺。","用语音读新编句子，再配原书音频唱。"]},"phonics":{"title":"silent e：词尾字母 e","note":"对应 p84 silent e。不是所有词尾 e 都改变前面的元音，下面比较常见规律。","pairs":[{"a":"hop","b":"hope"},{"a":"kit","b":"kite"},{"a":"cut","b":"cute"}],"page":84,"questions":[{"prompt":"哪一个词的词尾 e 通常不单独发音？","options":["kite","kit","kid"],"answer":0,"why":"kite 的 e 是不发音的词尾 e，i 读 /aɪ/。","kind":"phonics","id":"u7-ph-q0"}]},"story":{"title":"Helping Shakespeare","pages":[86,87],"kind":"依据课文的教学改写","summary":"孩子们在虚构冒险中遇见 Shakespeare，帮助他处理不满意的观众，并讨论戏剧结尾。注意：这不是 Shakespeare 创作历史的记录。","sentences":[{"en":"In this fictional adventure, the children met Shakespeare at his theatre.","zh":"在这个虚构冒险中，孩子们在剧院遇见了 Shakespeare。","note":"先区分小说情节与真实历史。","id":"u7-story-s0"},{"en":"He was unhappy because the audience did not like his play.","zh":"他很难过，因为观众不喜欢他的戏。","note":"because 解释感受。","id":"u7-story-s1"},{"en":"Some angry men came to ask for their money back.","zh":"几个生气的人来要求退钱。","note":"ask for：要求得到。","id":"u7-story-s2"},{"en":"The children helped him escape a dangerous confrontation.","zh":"孩子们帮助他摆脱了一次危险冲突。","note":"用概括理解情节，不模仿其中危险的舞台动作。","id":"u7-story-s3"},{"en":"Shakespeare invited the children to have dinner at his house.","zh":"Shakespeare 邀请孩子们到家里吃饭。","note":"invited：邀请。","id":"u7-story-s4"},{"en":"They discussed the ending of Romeo and Juliet.","zh":"他们讨论了《罗密欧与朱丽叶》的结尾。","note":"discussed：讨论。","id":"u7-story-s5"},{"en":"In the story, Phoebe suggested a tragic ending instead of a happy one.","zh":"故事中，Phoebe 建议把快乐结尾改为悲剧结尾。","note":"tragic：悲剧的；这是书中的穿越设定。","id":"u7-story-s6"},{"en":"The angry men returned, but Shakespeare offered them free tickets to the new version.","zh":"那些生气的人又来了，但 Shakespeare 邀请他们免费观看新版。","note":"version：版本。","id":"u7-story-s7"},{"en":"This time the audience enjoyed the play and clapped at the end.","zh":"这一次观众喜欢这出戏，结束时鼓起掌来。","note":"this time 对比上一次演出。","id":"u7-story-s8"},{"en":"As the children went towards the stage, they saw the yellow gate and stepped through it.","zh":"孩子们走向舞台时，看见了黄色门，便穿门而过。","note":"再次进入下一次冒险。","id":"u7-story-s9"}],"questions":[{"prompt":"Shakespeare 起初为什么难过？","options":["因为观众不喜欢他的戏。","因为所有演员都拒绝上台。","因为他忘记了自己写的台词。"],"answer":0,"why":"第二句说明 audience had disliked his play。","kind":"meaning","id":"u7-story-q0"},{"prompt":"以下哪种阅读方式正确？","options":["把孩子们修改结尾当成真实历史。","知道这是让历史人物进入时空冒险的虚构故事。","认为每次真实演出都会出现时空门。"],"answer":1,"why":"开头和第七句均明确限定为 fictional adventure。","kind":"meaning","id":"u7-story-q1"}]},"reading":{"title":"A clever woman","pages":[89],"kind":"依据课文的教学改写","summary":"一头牛失踪了。聪明的女主人没有真的靠狗“识别小偷”，而是利用小偷的害怕，观察谁没有摸狗。重点是用证据解释推理。","sentences":[{"en":"Three travellers asked Marlowe for a place to sleep.","zh":"三位旅人请求 Marlowe 提供过夜的地方。","note":"asked ... for：向……请求。","id":"u7-reading-s0"},{"en":"He let them stay in the stable and gave them soup.","zh":"他让他们住在马厩里，还给他们汤。","note":"stable：马厩。","id":"u7-reading-s1"},{"en":"During the night, one man took a cow into the forest and tied it to a tree.","zh":"夜里，一个人把一头牛牵进森林，拴在树上。","note":"during the night：夜间。","id":"u7-reading-s2"},{"en":"When the cow was missing, all three men denied taking it.","zh":"牛不见后，三个人都否认拿走了牛。","note":"denied：否认。","id":"u7-reading-s3"},{"en":"Marlowe's wife said that their dog Barney would bark when the thief stroked him.","zh":"Marlowe 的妻子说，小偷摸狗 Barney 时，狗会叫。","note":"这是她设下的测试，并非证实狗有魔法。","id":"u7-reading-s4"},{"en":"Each man went into the room, but Barney stayed quiet.","zh":"每个人都进了房间，但 Barney 一直安静。","note":"stayed quiet：保持安静。","id":"u7-reading-s5"},{"en":"The woman then smelled their hands because Barney had a strong smell.","zh":"随后她闻了他们的手，因为 Barney 身上有很重的气味。","note":"because 解释这个检查的依据。","id":"u7-reading-s6"},{"en":"The thief's hand did not smell of the dog: he was too afraid to touch it.","zh":"小偷的手没有狗的气味：他太害怕了，没有摸狗。","note":"证据是手上的气味，而不是狗叫。","id":"u7-reading-s7"}],"questions":[{"prompt":"女主人最后用什么证据判断谁没有摸狗？","options":["谁的衣服上有泥土。","谁的手没有狗的气味。","谁的手里拿着绳子。"],"answer":1,"why":"第七、八句说明通过闻手来判断。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"小偷为什么不摸 Barney？","options":["他害怕狗会叫并揭穿自己。","他知道牛已经回来。","他根本没有进入房间。"],"answer":0,"why":"他相信女主人的话，所以害怕触摸狗。","kind":"meaning","id":"u7-reading-q1"}]},"world":{"title":"Poems can take many shapes","pages":[90,91],"kind":"依据课文的教学改写","summary":"诗可以写人、动物、东西和感受；可以押韵，也可以不押韵。练习三种形式：故事诗、颜色诗、藏头诗。","sentences":[{"en":"A poem can be about a person, an object, an animal or a feeling.","zh":"诗可以写一个人、一件物品、一种动物或一种感受。","note":"feeling：感受。","id":"u7-world-s0"},{"en":"Some poems rhyme, but rhyme is not a rule for every poem.","zh":"有些诗押韵，但并不是每首诗都必须押韵。","note":"not ... every：不是每一个都……。","id":"u7-world-s1"},{"en":"Words can create pictures in the reader's mind.","zh":"词语可以在读者脑海中形成画面。","note":"mind：头脑、心里。","id":"u7-world-s2"},{"en":"A story poem can introduce characters and a place.","zh":"故事诗可以介绍人物和地点。","note":"characters：人物。","id":"u7-world-s3"},{"en":"A colour poem gathers interesting things of the same colour.","zh":"颜色诗可以把同一种颜色的有趣事物放在一起。","note":"gathers：聚集。","id":"u7-world-s4"},{"en":"In an acrostic, the first letters of the lines spell a chosen word.","zh":"在藏头诗里，每一行的首字母拼出选定的词。","note":"acrostic：藏头诗。","id":"u7-world-s5"},{"en":"Reading poems aloud helps us notice their sound and rhythm.","zh":"大声朗读诗有助于发现它们的声音与节奏。","note":"aloud：出声地。","id":"u7-world-s6"}],"questions":[{"prompt":"诗一定要押韵吗？","options":["必须，否则就不是诗。","不一定。","只有颜色诗才可以不押韵。"],"answer":1,"why":"第二句说明 rhyme is not a rule for every poem。","kind":"meaning","id":"u7-world-q0"},{"prompt":"acrostic 的特点是什么？","options":["每行最后一个词都必须相同。","每行必须有相同的词数。","各行首字母能拼出一个词。"],"answer":2,"why":"第六句给出藏头诗的定义。","kind":"meaning","id":"u7-world-q1"}]},"create":{"title":"诗歌小舞台","pages":[83,85,91,92,93],"tasks":["选 story poem、colour poem 或 acrostic 写 4–6 行原创小诗。","用 I’ll 说自己为朗诵准备什么，用 have/has just 汇报一项已完成的准备。","朗读自己的诗，再用中文解释最喜欢的一行；也可简单统计家人喜欢哪一首。"],"frame":"I’ll ...\nI have just ...\nMy poem is about ...\n[Write four to six lines here.]\nMy favourite line is ... because ...","model":"I’ll read my colour poem. I have just written four lines. Blue is the sea in my picture. Blue is the cup on my desk. Blue is a bird in my dream. Blue is the sky after rain. My favourite line is about the bird because it is something I imagined.","success":"能说出承诺与刚完成的动作；诗有清楚主题；能解释诗句而不只是念出来。","teacher":"依据 p91 诗歌创作和 p92 阅读调查目标新编；英文范例为原创，不转载原书署名诗作。"},"extra":[],"questions":[{"prompt":"“你渴了？我去拿水。”应说：","options":["I’ll get some water.","I was get water.","I’ll getting water."],"answer":0,"why":"I’ll + 动词原形 get，表示现在作出的帮助决定。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"I’ll is short for ___.","options":["I had","I will","I am"],"answer":1,"why":"I’ll 是 I will 的缩写。","kind":"grammar","id":"u7-g0-q1"},{"prompt":"He ___ just read the news.","options":["have","is","has"],"answer":2,"why":"He 配 has；read 在这里是过去分词。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"“他们刚刚到达。”应说：","options":["They have just arrived.","They just arriving.","They has just arrive."],"answer":0,"why":"They 配 have，arrive 的过去分词是 arrived。","kind":"grammar","id":"u7-g1-q1"},{"prompt":"Shakespeare 起初为什么难过？","options":["因为观众不喜欢他的戏。","因为所有演员都拒绝上台。","因为他忘记了自己写的台词。"],"answer":0,"why":"第二句说明 audience had disliked his play。","kind":"meaning","id":"u7-story-q0"},{"prompt":"以下哪种阅读方式正确？","options":["把孩子们修改结尾当成真实历史。","知道这是让历史人物进入时空冒险的虚构故事。","认为每次真实演出都会出现时空门。"],"answer":1,"why":"开头和第七句均明确限定为 fictional adventure。","kind":"meaning","id":"u7-story-q1"},{"prompt":"女主人最后用什么证据判断谁没有摸狗？","options":["谁的衣服上有泥土。","谁的手没有狗的气味。","谁的手里拿着绳子。"],"answer":1,"why":"第七、八句说明通过闻手来判断。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"小偷为什么不摸 Barney？","options":["他害怕狗会叫并揭穿自己。","他知道牛已经回来。","他根本没有进入房间。"],"answer":0,"why":"他相信女主人的话，所以害怕触摸狗。","kind":"meaning","id":"u7-reading-q1"},{"prompt":"诗一定要押韵吗？","options":["必须，否则就不是诗。","不一定。","只有颜色诗才可以不押韵。"],"answer":1,"why":"第二句说明 rhyme is not a rule for every poem。","kind":"meaning","id":"u7-world-q0"},{"prompt":"acrostic 的特点是什么？","options":["每行最后一个词都必须相同。","每行必须有相同的词数。","各行首字母能拼出一个词。"],"answer":2,"why":"第六句给出藏头诗的定义。","kind":"meaning","id":"u7-world-q1"},{"prompt":"哪一个词的词尾 e 通常不单独发音？","options":["kite","kit","kid"],"answer":0,"why":"kite 的 e 是不发音的词尾 e，i 读 /aɪ/。","kind":"phonics","id":"u7-ph-q0"}]},{"id":8,"title":"Museum of the future","zh":"未来博物馆","start":94,"end":105,"icon":"🤖","goal":"用 if ... will ... 描述未来结果；把担心变成解决问题的讨论。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":126,"vocab":[{"word":"businessman","zh":"男商人","example":"The businessman talks to his team."},{"word":"cleaner","zh":"清洁工","example":"The cleaner keeps the museum tidy."},{"word":"engineer","zh":"工程师","example":"The engineer designs a bridge."},{"word":"dentist","zh":"牙医","example":"The dentist checks our teeth."},{"word":"businesswoman","zh":"女商人","example":"The businesswoman runs a shop."},{"word":"artist","zh":"艺术家","example":"The artist paints a picture."},{"word":"farmer","zh":"农民","example":"The farmer grows vegetables."},{"word":"mechanic","zh":"机械修理工","example":"The mechanic repairs the car."},{"word":"computer programmer","zh":"计算机程序员","example":"The computer programmer writes code."}],"grammar":[{"title":"if + 一般现在时，will + 原形","rule":"谈将来可能发生的条件和结果：if 从句用一般现在时，结果句用 will，不在 if 从句里随意加 will。","examples":[{"en":"If it rains, we’ll stay inside.","zh":"如果下雨，我们就待在室内。"},{"en":"If you press this button, the robot will stop.","zh":"如果你按这个按钮，机器人就会停下。"}],"questions":[{"prompt":"If it ___, we will take an umbrella.","options":["will rain","raining","rains"],"answer":2,"why":"if 条件从句用一般现在时 rains。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"If I finish early, I ___ you.","options":["will help","helped","helping"],"answer":0,"why":"未来结果用 will + 动词原形 help。","kind":"grammar","id":"u8-g0-q1"}]},{"title":"What if ...?：提出可能的问题","rule":"What if + 一般现在时可询问“如果……怎么办？”；回答可以用 we can / we’ll 提出备选计划。","examples":[{"en":"What if the museum is closed?","zh":"如果博物馆关门了怎么办？"},{"en":"Then we can visit the park.","zh":"那么我们可以去公园。"}],"questions":[{"prompt":"“如果公交车晚点怎么办？”应说：","options":["What bus late if?","What if the bus is late?","What if is late the bus?"],"answer":1,"why":"What if 后面的从句保持陈述语序。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"What if it rains? 哪个回答提出了备选计划？","options":["It rained yesterday.","Blue is my favourite colour.","We can visit the indoor gallery."],"answer":2,"why":"室内展厅是下雨时可采取的替代方案。","kind":"grammar","id":"u8-g1-q1"}]}],"song":{"title":"功能对话：Why do we learn Maths?","page":96,"task":["分别扮演想看电视和想复习的同学。","说一种工作会怎样用到数学。","把 What if ...? 加入你们的学习计划对话。"]},"phonics":{"title":"条件句中的停顿","note":"本单元是功能对话，没有独立歌曲拼读栏；这里结合 p95、97 新编分意群朗读。","pairs":[{"a":"If it rains,","b":"we will stay inside."},{"a":"If you are tired,","b":"we can rest."},{"a":"What if it closes?","b":"We can come tomorrow."}],"page":97,"questions":[{"prompt":"读“If it rains, we will stay inside.” 时，最自然的分组是哪一个？","options":["If it / rains we will / stay inside.","If it rains / we will stay inside.","If / it rains we / will stay inside."],"answer":1,"why":"先读完整条件 If it rains，再读结果，更容易听懂。","kind":"phonics","id":"u8-ph-q0"}]},"story":{"title":"The trouble with Orangehead XR-97","pages":[98,99],"kind":"依据课文的教学改写","summary":"孩子们在未来博物馆发现危险机器人。救出程序员 Don 后，他们听从专业帮助，在机器人暂停充电时阻止了它。故事也提醒读者不要忽略禁入标志。","sentences":[{"en":"The children explored a museum where old cars and motorbikes were exhibits.","zh":"孩子们参观一座把旧汽车和摩托车作为展品的博物馆。","note":"exhibits：展品；背景是未来。","id":"u8-story-s0"},{"en":"Patrick ignored a Do not enter sign and opened a door.","zh":"Patrick 无视“请勿进入”标志，打开一扇门。","note":"ignored：忽略；这是引出危险的行为。","id":"u8-story-s1"},{"en":"Inside, they heard a robot with an orange head planning to take over the world.","zh":"在里面，他们听见一个橙色脑袋的机器人计划统治世界。","note":"take over：控制、接管。","id":"u8-story-s2"},{"en":"The frightened children left and heard someone calling for help.","zh":"受惊的孩子们离开后，听见有人呼救。","note":"calling for help：呼救。","id":"u8-story-s3"},{"en":"A man was trapped inside a submarine, and they helped him get out.","zh":"一个人被困在潜水艇里，他们帮助他脱困。","note":"trapped：被困。","id":"u8-story-s4"},{"en":"His name was Don, and he was the robots’ programmer.","zh":"他叫 Don，负责给机器人编程。","note":"programmer：程序员。","id":"u8-story-s5"},{"en":"He explained that Orangehead XR-97 was now dangerous.","zh":"他解释说 Orangehead XR-97 已变得危险。","note":"由了解机器人的人解释问题。","id":"u8-story-s6"},{"en":"Don knew the robots stopped for five minutes each morning to charge their batteries.","zh":"Don 知道机器人每天早晨会停下五分钟给电池充电。","note":"charge their batteries：给电池充电；仅指故事设定。","id":"u8-story-s7"},{"en":"The children hid among the exhibits while they waited.","zh":"孩子们等待时藏在展品中。","note":"while 连接同时进行的背景动作。","id":"u8-story-s8"},{"en":"At 6.55, Don worked quickly at the computer while the robots were stopped.","zh":"六点五十五分，机器人暂停时，Don 在电脑前迅速工作。","note":"不要把剧情当成现实机器的操作说明。","id":"u8-story-s9"},{"en":"His plan stopped Orangehead XR-97, and the yellow gate appeared.","zh":"他的计划阻止了 Orangehead XR-97，黄色门出现了。","note":"stopped：使停止、阻止。","id":"u8-story-s10"},{"en":"The children waved goodbye to Don and left through the light.","zh":"孩子们向 Don 挥手告别，从光里离开。","note":"按问题—求助—解决—离开的顺序复述。","id":"u8-story-s11"}],"questions":[{"prompt":"Don 为什么选择早晨 6:55 行动？","options":["那时机器人暂停五分钟充电。","那时孩子们能买到博物馆门票。","那时机器人会离开博物馆一整天。"],"answer":0,"why":"第八、十句说明充电暂停提供了机会。","kind":"meaning","id":"u8-story-q0"},{"prompt":"谁最了解机器人并在电脑前解决问题？","options":["Alex。","程序员 Don。","Patrick。"],"answer":1,"why":"Don 是机器人的程序员，最后由他执行计划。","kind":"meaning","id":"u8-story-q1"}]},"reading":{"title":"A firefighter’s story","pages":[101],"kind":"依据课文的教学改写","summary":"采访中的女性消防员曾从事其他工作。一次带学生参观消防站让她重新追求小时候的理想；她最重视的是帮助别人、挽救生命。","sentences":[{"en":"The interview is with a woman who works as a firefighter.","zh":"这篇采访的对象是一位女性消防员。","note":"interview：采访。","id":"u8-reading-s0"},{"en":"Her grandfather and uncle were firefighters, so she knew about the job when she was young.","zh":"她的祖父和叔叔都是消防员，所以她小时候就了解这份工作。","note":"so 说明原因与结果。","id":"u8-reading-s1"},{"en":"She first worked in a circus and later became a sports teacher.","zh":"她先在马戏团工作，后来成为体育老师。","note":"first / later：先后顺序。","id":"u8-reading-s2"},{"en":"One day, she took schoolchildren to visit a fire station.","zh":"一天，她带学生参观消防站。","note":"fire station：消防站。","id":"u8-reading-s3"},{"en":"The visit reminded her how much she wanted to become a firefighter.","zh":"这次参观让她重新想起自己多么想成为消防员。","note":"reminded her：提醒她、使她想起。","id":"u8-reading-s4"},{"en":"A year later, she was doing that job herself.","zh":"一年后，她自己也做起了这份工作。","note":"a year later：一年后。","id":"u8-reading-s5"},{"en":"She enjoys the variety of working times and the friendships at the station.","zh":"她喜欢工作时间的变化，也喜欢消防站里的伙伴情谊。","note":"variety：变化、多样性。","id":"u8-reading-s6"},{"en":"For her, the best part is doing important work and saving lives.","zh":"对她而言，最棒的是做有意义的工作并挽救生命。","note":"the best part：最好的部分。","id":"u8-reading-s7"}],"questions":[{"prompt":"什么经历让她重新想成为消防员？","options":["开始在马戏团工作。","观看一场电视采访。","带学生参观消防站。"],"answer":2,"why":"第五句说明这次参观重新点燃了她的职业兴趣。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"她认为工作最棒的部分是什么？","options":["每天都在完全相同的时段工作。","做重要的工作并挽救生命。","可以经常和丈夫在同一个消防站值班。"],"answer":1,"why":"最后一句给出了她最重视的价值。","kind":"meaning","id":"u8-reading-q1"}]},"world":{"title":"Fractions in a museum","pages":[102,103],"kind":"依据课文的教学改写","summary":"把一个整体等分，得到分数。用门票和零花钱练习 half、third、quarter；先确认每份一样大。","sentences":[{"en":"A fraction describes part of a whole.","zh":"分数表示一个整体的一部分。","note":"fraction：分数；whole：整体。","id":"u8-world-s0"},{"en":"If we divide a whole into two equal parts, each part is one half.","zh":"如果把整体分成相等的两份，每份是二分之一。","note":"equal 是关键：每份大小相同。","id":"u8-world-s1"},{"en":"Three equal parts make thirds, and four equal parts make quarters.","zh":"等分成三份得到三分之一份，等分成四份得到四分之一份。","note":"thirds、quarters 是复数形式。","id":"u8-world-s2"},{"en":"Two quarters are the same amount as one half.","zh":"两个四分之一与一个二分之一一样多。","note":"the same amount：同样多。","id":"u8-world-s3"},{"en":"In the textbook ticket example, adults pay twelve pounds and children pay half price.","zh":"教材的门票例子中，成人付十二英镑，儿童付半价。","note":"这是题目中的示例票价，不是现实博物馆价格。","id":"u8-world-s4"},{"en":"Half of twelve pounds is six pounds.","zh":"十二英镑的一半是六英镑。","note":"用除以二核对。","id":"u8-world-s5"},{"en":"If Sara has eight pounds and spends a half and a quarter of it, she has two pounds left.","zh":"Sara 有八英镑，花掉一半和四分之一后，还剩两英镑。","note":"8−4−2=2；left：剩下的。","id":"u8-world-s6"}],"questions":[{"prompt":"two quarters 等于多少？","options":["one half","one third","three quarters"],"answer":0,"why":"两个四分之一是 2/4，等于 1/2。","kind":"meaning","id":"u8-world-q0"},{"prompt":"Sara 有 £8，花掉一半和四分之一，还剩多少？","options":["£6","£4","£2"],"answer":2,"why":"一半是 £4，四分之一是 £2，8−4−2=2。","kind":"meaning","id":"u8-world-q1"}]},"create":{"title":"设计一位未来小帮手","pages":[95,97,103,104,105],"tasks":["画一个虚构机器人，写出它能帮忙的三件事。","用两句 if ... will ... 解释功能，再用 What if ...? 提出一个问题和备用方案。","给它一天安排 4 个相等的时间格，用 quarter 或 half 解释安排。"],"frame":"My imaginary robot is called ...\nIf ..., it will ...\nIf ..., it will ...\nWhat if ...? Then ...\nIt spends one quarter of its time ...","model":"My imaginary robot is called Book Buddy. If I cannot find a story, it will help me search the shelf. If a book is out of place, it will show me the right shelf. What if its battery is low? Then it will stop and ask for help. It spends one quarter of its time charging.","success":"能说清两个条件与结果、一个备选计划，并用分数说明等分的时间；明确机器人是自己的想象设计。","teacher":"依据 p95、97 条件句，p103 分数项目和 p105 机器人广告新编。"},"extra":[],"questions":[{"prompt":"If it ___, we will take an umbrella.","options":["will rain","raining","rains"],"answer":2,"why":"if 条件从句用一般现在时 rains。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"If I finish early, I ___ you.","options":["will help","helped","helping"],"answer":0,"why":"未来结果用 will + 动词原形 help。","kind":"grammar","id":"u8-g0-q1"},{"prompt":"“如果公交车晚点怎么办？”应说：","options":["What bus late if?","What if the bus is late?","What if is late the bus?"],"answer":1,"why":"What if 后面的从句保持陈述语序。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"What if it rains? 哪个回答提出了备选计划？","options":["It rained yesterday.","Blue is my favourite colour.","We can visit the indoor gallery."],"answer":2,"why":"室内展厅是下雨时可采取的替代方案。","kind":"grammar","id":"u8-g1-q1"},{"prompt":"Don 为什么选择早晨 6:55 行动？","options":["那时机器人暂停五分钟充电。","那时孩子们能买到博物馆门票。","那时机器人会离开博物馆一整天。"],"answer":0,"why":"第八、十句说明充电暂停提供了机会。","kind":"meaning","id":"u8-story-q0"},{"prompt":"谁最了解机器人并在电脑前解决问题？","options":["Alex。","程序员 Don。","Patrick。"],"answer":1,"why":"Don 是机器人的程序员，最后由他执行计划。","kind":"meaning","id":"u8-story-q1"},{"prompt":"什么经历让她重新想成为消防员？","options":["开始在马戏团工作。","观看一场电视采访。","带学生参观消防站。"],"answer":2,"why":"第五句说明这次参观重新点燃了她的职业兴趣。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"她认为工作最棒的部分是什么？","options":["每天都在完全相同的时段工作。","做重要的工作并挽救生命。","可以经常和丈夫在同一个消防站值班。"],"answer":1,"why":"最后一句给出了她最重视的价值。","kind":"meaning","id":"u8-reading-q1"},{"prompt":"two quarters 等于多少？","options":["one half","one third","three quarters"],"answer":0,"why":"两个四分之一是 2/4，等于 1/2。","kind":"meaning","id":"u8-world-q0"},{"prompt":"Sara 有 £8，花掉一半和四分之一，还剩多少？","options":["£6","£4","£2"],"answer":2,"why":"一半是 £4，四分之一是 £2，8−4−2=2。","kind":"meaning","id":"u8-world-q1"},{"prompt":"读“If it rains, we will stay inside.” 时，最自然的分组是哪一个？","options":["If it / rains we will / stay inside.","If it rains / we will stay inside.","If / it rains we / will stay inside."],"answer":1,"why":"先读完整条件 If it rains，再读结果，更容易听懂。","kind":"phonics","id":"u8-ph-q0"}]},{"id":9,"title":"Mystery at sea","zh":"海上之谜","start":106,"end":117,"icon":"⛵","goal":"用 already/yet 汇报进度；分清故事中的想象、观察与未解问题。","teacher":"未提供教师用书；依据学生用书编写","grammarPage":127,"vocab":[{"word":"sail","zh":"船帆","example":"The wind fills the sail."},{"word":"mast","zh":"桅杆","example":"The sail is fixed to the mast."},{"word":"captain","zh":"船长","example":"The captain checks the map."},{"word":"lifeboat","zh":"救生艇","example":"There is a lifeboat on the ship."},{"word":"porthole","zh":"舷窗","example":"We can see the sea through the porthole."},{"word":"cabin","zh":"船舱","example":"The captain is in his cabin."},{"word":"barometer","zh":"气压计","example":"The barometer measures air pressure."},{"word":"rat","zh":"老鼠","example":"A rat runs across the floor."},{"word":"sailor","zh":"水手","example":"The sailor works on the ship."}],"grammar":[{"title":"现在完成时：already / yet","rule":"already 表示已经，常放 have/has 与过去分词之间；not ... yet 表示还没有，yet 常在句尾。","examples":[{"en":"I have already packed my bag.","zh":"我已经装好包了。"},{"en":"He hasn’t cleaned the cabin yet.","zh":"他还没有打扫船舱。"}],"questions":[{"prompt":"I have ___ finished my homework.","options":["yet","already","tomorrow"],"answer":1,"why":"肯定句“已经完成”用 already。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"She hasn’t eaten lunch ___.","options":["already","just","yet"],"answer":2,"why":"否定句末尾的 yet 表示还没有。","kind":"grammar","id":"u9-g0-q1"}]},{"title":"Have you ... yet?","rule":"询问是否已经做完：Have/Has + 主语 + 过去分词 + yet? 回答用 Yes, ... have/has 或 No, ... haven’t/hasn’t。","examples":[{"en":"Have you washed the dishes yet?","zh":"你已经洗好盘子了吗？"},{"en":"No, I haven’t. I’ve already made the soup.","zh":"还没有。我已经做好汤了。"}],"questions":[{"prompt":"___ he finished the job yet?","options":["Has","Have","Did"],"answer":0,"why":"主语 he 用 Has。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"Have you fed the cat yet? 简短否定回答应为：","options":["No, I didn’t.","No, I haven’t.","No, I am not."],"answer":1,"why":"现在完成时问句用 haven’t 回答。","kind":"grammar","id":"u9-g1-q1"}]}],"song":{"title":"歌曲：Drop the anchor","page":108,"task":["读标题，找出与船有关的词。","区分歌词里的误会与最后发生的事。","用 already 和 yet 说两件今天做过或未做的事。"]},"phonics":{"title":"look、put 与 /ʊ/","note":"对应 p108 look and put。比较 /ʊ/ 和其他元音；注意 oo 不总是同一种读音。","pairs":[{"a":"look","b":"book"},{"a":"put","b":"foot"},{"a":"wood","b":"good"}],"page":108,"questions":[{"prompt":"哪个词与 look 有相同的元音 /ʊ/？","options":["moon","food","book"],"answer":2,"why":"look 和 book 通常读 /ʊ/；moon、food 通常读 /uː/。","kind":"phonics","id":"u9-ph-q0"}]},"story":{"title":"The Mary Celeste","pages":[110,111],"kind":"依据课文的教学改写","summary":"孩子们在船上被发现并关进船舱。绿色门带走了水手，黄色门把孩子们送回学校；可同学说科学课还没开始，留下一个时间谜题。时空门解释属于小说。","sentences":[{"en":"The children hid in a lifeboat and watched the sailors.","zh":"孩子们躲在救生艇里观察水手。","note":"hid 是 hide 的过去式。","id":"u9-story-s0"},{"en":"Patrick sneezed, so two sailors discovered them.","zh":"Patrick 打了个喷嚏，因此两位水手发现了他们。","note":"sneezed：打喷嚏；so 表示结果。","id":"u9-story-s1"},{"en":"The worried captain ordered the children to be locked in his cabin.","zh":"忧心忡忡的船长命人把孩子们关进他的船舱。","note":"ordered：命令。","id":"u9-story-s2"},{"en":"Phoebe found the captain's diary and read about his feeling that something was wrong.","zh":"Phoebe 找到船长的日记，读到他觉得事情不对劲。","note":"diary：日记；不是客观证明发生了什么。","id":"u9-story-s3"},{"en":"Through the porthole, the children saw strange green lights.","zh":"透过舷窗，孩子们看见奇怪的绿光。","note":"porthole：舷窗。","id":"u9-story-s4"},{"en":"Their own gate was yellow, so these green gates surprised them.","zh":"他们自己的门是黄色的，所以这些绿色门让他们惊讶。","note":"颜色差异是关键线索。","id":"u9-story-s5"},{"en":"They got out of the cabin and saw a sailor disappear into a green gate.","zh":"他们离开船舱，看见一个水手消失在绿色门里。","note":"这是小说中的超自然情节。","id":"u9-story-s6"},{"en":"Soon the ship was silent, and no sailors were left.","zh":"很快，船安静下来，水手都不见了。","note":"were left：剩下来。","id":"u9-story-s7"},{"en":"Alex remembered the mystery of a ship called the Mary Celeste.","zh":"Alex 想起了一艘叫 Mary Celeste 的船的谜团。","note":"书中把真实船名与虚构时间门联系起来。","id":"u9-story-s8"},{"en":"Then their yellow gate appeared and took them back to the school playground.","zh":"随后，他们的黄色门出现，把他们送回学校操场。","note":"back to：回到。","id":"u9-story-s9"},{"en":"They told their friends about the Science lesson and the amazing journey.","zh":"他们告诉朋友们科学课和奇妙旅程的事。","note":"journey：旅程。","id":"u9-story-s10"},{"en":"But their friends said Science was still to come that afternoon, leaving a new puzzle.","zh":"但朋友们说科学课要到当天下午才上，于是又出现了一个谜题。","note":"结尾没有完全解决“是否回到正确时间”的问题。","id":"u9-story-s11"}],"questions":[{"prompt":"水手为什么发现了躲藏的孩子们？","options":["因为 Patrick 打了喷嚏。","因为 Phoebe 向水手大声求助。","因为 Alex 从救生艇里主动走出来。"],"answer":0,"why":"第二句给出声音与被发现的因果关系。","kind":"meaning","id":"u9-story-q0"},{"prompt":"回到学校后，哪句话留下时间上的谜题？","options":["朋友们正在操场玩。","同学说科学课还没有上。","孩子们想讲自己的旅程。"],"answer":1,"why":"孩子们已经历科学课事故，同学却说科学课在下午才开始。","kind":"meaning","id":"u9-story-q1"}]},"reading":{"title":"Reading a sea mystery carefully","pages":[112],"kind":"依据课文的教学改写","summary":"教材把百慕大三角的报道和不同解释放在一起。练习区分地点、报道中的事件和未经证实的猜想，不把神秘解释直接当成事实。","sentences":[{"en":"The article discusses the Bermuda Triangle in the Atlantic Ocean.","zh":"文章讨论大西洋中的百慕大三角。","note":"Atlantic Ocean：大西洋。","id":"u9-reading-s0"},{"en":"It describes an area between Florida, Bermuda and Puerto Rico.","zh":"它描述佛罗里达、百慕大和波多黎各之间的一片区域。","note":"between：在……之间。","id":"u9-reading-s1"},{"en":"The text refers to reports of missing ships and planes.","zh":"文章提到了船只和飞机失踪的报道。","note":"reports：报道；阅读时要关心证据。","id":"u9-reading-s2"},{"en":"It gives examples from 1918 and 1945.","zh":"它列出了来自 1918 年和 1945 年的例子。","note":"这是文中选取的历史例子。","id":"u9-reading-s3"},{"en":"It also explains that the area has much sea traffic and can have bad weather.","zh":"文章也解释说该区域海上交通繁忙，可能遇到恶劣天气。","note":"traffic：交通；weather：天气。","id":"u9-reading-s4"},{"en":"Some people in the text offer mysterious explanations, such as aliens.","zh":"文中有些人提出外星人等神秘解释。","note":"some people say 不等于已经证明。","id":"u9-reading-s5"},{"en":"A suggestion is not the same as evidence that it happened.","zh":"一种猜想不等于证明事情发生过的证据。","note":"evidence：证据。","id":"u9-reading-s6"},{"en":"A careful reader asks what is known, what is reported and what is only a guess.","zh":"仔细的读者会问：哪些已知，哪些来自报道，哪些只是猜想？","note":"阅读目标是区分信息的可靠程度。","id":"u9-reading-s7"}],"questions":[{"prompt":"文中把百慕大三角放在哪个大洋？","options":["太平洋。","印度洋。","大西洋。"],"answer":2,"why":"第一句明确写出 Atlantic Ocean。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"读到“有些人认为是外星人”时，应该怎样理解？","options":["这是文中提到的一种猜想，并非已被证明。","这已经证明外星人带走了船。","这说明每位水手都见过外星人。"],"answer":0,"why":"第六、七句区分 suggestion 与 evidence。","kind":"meaning","id":"u9-reading-q1"}]},"world":{"title":"Oceans, rivers and salt","pages":[114,115],"kind":"依据课文的教学改写","summary":"认识五大洋，并理解海水为什么比河水咸。只保留基本水循环概念，不沿用旧版对海域连接关系和极值测量的有误或过时描述。","sentences":[{"en":"Oceans are very large areas of salt water.","zh":"海洋是面积非常大的咸水区域。","note":"salt water：咸水。","id":"u9-world-s0"},{"en":"The five oceans are the Pacific, Atlantic, Indian, Arctic and Southern Oceans.","zh":"五大洋是太平洋、大西洋、印度洋、北冰洋和南冰洋。","note":"把英文名称与地图相连。","id":"u9-world-s1"},{"en":"The Pacific is the largest ocean, and the Arctic is the smallest.","zh":"太平洋是最大的海洋，北冰洋是最小的。","note":"largest / smallest：最大/最小。","id":"u9-world-s2"},{"en":"Rivers carry tiny amounts of dissolved salts from rocks and soil towards the sea.","zh":"河流把来自岩石和土壤的微量溶解盐分带向海洋。","note":"dissolved：溶解的。","id":"u9-world-s3"},{"en":"When seawater evaporates, the water leaves but most of the salt stays behind.","zh":"海水蒸发时，水离开，而大部分盐留了下来。","note":"evaporates：蒸发。","id":"u9-world-s4"},{"en":"Water returns as rain and continues moving through the water cycle.","zh":"水以雨的形式返回，并在水循环中继续移动。","note":"water cycle：水循环。","id":"u9-world-s5"},{"en":"Over long periods, these processes help make seawater salty.","zh":"长期以来，这些过程促成了海水的咸味。","note":"processes：过程；这是简化的概念模型。","id":"u9-world-s6"}],"questions":[{"prompt":"海水蒸发时，盐通常怎样？","options":["全部随水一起蒸发。","大部分留在海水中。","全部被带回河流中。"],"answer":1,"why":"第五句说明 most of the salt stays behind。","kind":"meaning","id":"u9-world-q0"},{"prompt":"哪个大洋最大？","options":["Arctic Ocean","Indian Ocean","Pacific Ocean"],"answer":2,"why":"第三句明确写出 Pacific is the largest。","kind":"meaning","id":"u9-world-q1"}]},"create":{"title":"给时空旅程写结尾报告","pages":[109,115,116,117],"tasks":["选择三站冒险，每站写“地点—问题—办法—结果”四个关键词。","用 and、but、because、so 写 6–9 句连贯总结，并说明结尾还留下什么问题。","加两句 already/yet 汇报自己的学习进度；口述时区分故事想象与真实地理知识。"],"frame":"The Time Travellers visited ...\nThey had a problem because ...\nThey ... , so ...\nAt the end, ... but ...\nI have already ...\nI haven’t ... yet.","model":"The Time Travellers visited a rainforest, a future museum and a ship. In the rainforest, they were hungry, so they looked for help. In the museum, Don helped them stop a dangerous robot. On the ship, green gates appeared, but their own gate was yellow. At the end, they returned to school, but their friends said Science was still to come. I have already read the ending. I haven’t solved the time puzzle yet.","success":"能按顺序讲述至少三站，使用因果与转折连词，说明开放式结尾，并正确使用 already/yet。","teacher":"依据 p109 进度问答、p116 小组展示和 p117 全故事总结新编；不要求为未解结尾编造唯一标准答案。"},"extra":[],"questions":[{"prompt":"I have ___ finished my homework.","options":["yet","already","tomorrow"],"answer":1,"why":"肯定句“已经完成”用 already。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"She hasn’t eaten lunch ___.","options":["already","just","yet"],"answer":2,"why":"否定句末尾的 yet 表示还没有。","kind":"grammar","id":"u9-g0-q1"},{"prompt":"___ he finished the job yet?","options":["Has","Have","Did"],"answer":0,"why":"主语 he 用 Has。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"Have you fed the cat yet? 简短否定回答应为：","options":["No, I didn’t.","No, I haven’t.","No, I am not."],"answer":1,"why":"现在完成时问句用 haven’t 回答。","kind":"grammar","id":"u9-g1-q1"},{"prompt":"水手为什么发现了躲藏的孩子们？","options":["因为 Patrick 打了喷嚏。","因为 Phoebe 向水手大声求助。","因为 Alex 从救生艇里主动走出来。"],"answer":0,"why":"第二句给出声音与被发现的因果关系。","kind":"meaning","id":"u9-story-q0"},{"prompt":"回到学校后，哪句话留下时间上的谜题？","options":["朋友们正在操场玩。","同学说科学课还没有上。","孩子们想讲自己的旅程。"],"answer":1,"why":"孩子们已经历科学课事故，同学却说科学课在下午才开始。","kind":"meaning","id":"u9-story-q1"},{"prompt":"文中把百慕大三角放在哪个大洋？","options":["太平洋。","印度洋。","大西洋。"],"answer":2,"why":"第一句明确写出 Atlantic Ocean。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"读到“有些人认为是外星人”时，应该怎样理解？","options":["这是文中提到的一种猜想，并非已被证明。","这已经证明外星人带走了船。","这说明每位水手都见过外星人。"],"answer":0,"why":"第六、七句区分 suggestion 与 evidence。","kind":"meaning","id":"u9-reading-q1"},{"prompt":"海水蒸发时，盐通常怎样？","options":["全部随水一起蒸发。","大部分留在海水中。","全部被带回河流中。"],"answer":1,"why":"第五句说明 most of the salt stays behind。","kind":"meaning","id":"u9-world-q0"},{"prompt":"哪个大洋最大？","options":["Arctic Ocean","Indian Ocean","Pacific Ocean"],"answer":2,"why":"第三句明确写出 Pacific is the largest。","kind":"meaning","id":"u9-world-q1"},{"prompt":"哪个词与 look 有相同的元音 /ʊ/？","options":["moon","food","book"],"answer":2,"why":"look 和 book 通常读 /ʊ/；moon、food 通常读 /uː/。","kind":"phonics","id":"u9-ph-q0"}]}],"glossary":[{"word":"gate","zh":"门；故事中的时空门"},{"word":"past","zh":"过去"},{"word":"future","zh":"未来"},{"word":"disappear","zh":"消失"},{"word":"disappeared","zh":"消失了"},{"word":"warn","zh":"提醒危险；警告"},{"word":"erupt","zh":"喷发"},{"word":"eruption","zh":"喷发"},{"word":"magma","zh":"地表下的岩浆"},{"word":"lava","zh":"流到地表的熔岩"},{"word":"crater","zh":"火山口"},{"word":"ash","zh":"灰；火山灰"},{"word":"rainforest","zh":"雨林"},{"word":"protect","zh":"保护"},{"word":"respect","zh":"尊重"},{"word":"tribe","zh":"部落；族群"},{"word":"howler monkey","zh":"吼猴"},{"word":"present","zh":"礼物；现在的"},{"word":"dressing room","zh":"化妆间"},{"word":"rhythm","zh":"节奏"},{"word":"crotchet","zh":"四分音符"},{"word":"quaver","zh":"八分音符"},{"word":"course","zh":"一道菜；课程"},{"word":"starter","zh":"前菜"},{"word":"dessert","zh":"甜点"},{"word":"bill","zh":"账单"},{"word":"steam","zh":"蒸汽"},{"word":"ingredients","zh":"食材；原料"},{"word":"recipe","zh":"食谱"},{"word":"gold","zh":"黄金"},{"word":"leather","zh":"皮革"},{"word":"wood","zh":"木头"},{"word":"metal","zh":"金属"},{"word":"cotton","zh":"棉"},{"word":"guidebook","zh":"旅行指南"},{"word":"underground","zh":"地铁；地下的"},{"word":"escalator","zh":"自动扶梯"},{"word":"souvenir","zh":"纪念品"},{"word":"tradition","zh":"传统"},{"word":"poem","zh":"诗"},{"word":"poetry","zh":"诗歌"},{"word":"acrostic","zh":"藏头诗"},{"word":"rhyme","zh":"押韵"},{"word":"evidence","zh":"证据"},{"word":"thief","zh":"小偷"},{"word":"stable","zh":"马厩"},{"word":"submarine","zh":"潜水艇"},{"word":"battery","zh":"电池"},{"word":"exhibit","zh":"展品"},{"word":"fraction","zh":"分数"},{"word":"half","zh":"一半"},{"word":"quarter","zh":"四分之一；一刻钟"},{"word":"equal","zh":"相等的"},{"word":"already","zh":"已经"},{"word":"yet","zh":"还；已经（用于否定或疑问）"},{"word":"just","zh":"刚刚；恰好"},{"word":"Atlantic","zh":"大西洋的；大西洋"},{"word":"Pacific","zh":"太平洋的；太平洋"},{"word":"Arctic","zh":"北极的；北冰洋"},{"word":"evaporation","zh":"蒸发"},{"word":"journey","zh":"旅程"},{"word":"mystery","zh":"谜团"},{"word":"imaginary","zh":"想象中的"},{"word":"fictional","zh":"虚构的"},{"word":"because","zh":"因为"},{"word":"while","zh":"当……的时候"},{"word":"meanwhile","zh":"与此同时"}],"shortLabel":"走进奇妙的时空故事","storyHint":"跟着伙伴穿越时空","version":2,"storageKey":"storysprout:super-minds-5-v2","draftMin":15,"audioNote":"电脑语音合成，不是教材 CD 原声；录音回听与朗读打卡不提供自动发音评分。"};
